/** All translations for zizhitongjian ch.161 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第161卷", literal: "Comprehensive Mirror in Aid of Governance, Volume 161", idiomatic: "Comprehensive Mirror in Aid of Governance, Volume 161" },
  { zh: "【梁紀十七】　著雍執徐，一年。", literal: "[Liang Records 17] Zhiyong Zhixu; one year in all.", idiomatic: "[Liang Records 17] Zhiyong Zhixu—one year in all." },
  { zh: "高祖武皇帝十七太清二年（", literal: "Great Ancestor Emperor Wu, seventeenth year of the Taqing era (", idiomatic: "Emperor Wu of Liang, seventeenth year of Taqing (" },
  { zh: "戊辰，公元五四八年）", literal: "wuchen, 548 CE)", idiomatic: "wuchen, AD 548)" },
  { zh: "春，正月，己亥，慕容紹宗以鐵騎五千夾擊侯景，景誑其眾曰：「汝輩家屬已為高澄所殺。", literal: "In spring, the first month, on jihai, Murong Shaozong with five thousand iron cavalry attacked Hou Jing from both flanks; Jing deceived his troops, saying: \"Your families have all been killed by Gao Cheng.", idiomatic: "In spring, the first month, on jihai, Murong Shaozong struck Hou Jing with five thousand iron cavalry from both flanks. Jing lied to his men: \"Gao Cheng has killed your families." },
  { zh: "」眾信之。", literal: "\" The troops believed him.", idiomatic: "\" The troops believed him." },
  { zh: "紹宗遙呼曰：「汝輩家屬並完，若歸，官勳如舊。", literal: "Shaozong shouted from afar: \"Your families are all safe; if you return, rank and merit will be as before.", idiomatic: "Shaozong shouted from afar: \"Your families are all safe. Return, and rank and merit stay as before." },
  { zh: "」被發向北斗為誓。", literal: "\" He let down his hair and swore toward the Northern Dipper.", idiomatic: "\" He let down his hair and swore toward the Northern Dipper." },
  { zh: "景士卒不樂南渡，其將暴顯等各帥所部降於紹宗。", literal: "Jing's soldiers were unwilling to cross south; his generals Bao Xian and others each led their commands in surrender to Shaozong.", idiomatic: "Jing's soldiers refused to cross south; his generals Bao Xian and others each surrendered their commands to Shaozong." },
  { zh: "景眾大潰，爭赴渦水，水為之不流。", literal: "Jing's army collapsed in great rout, rushing into the Wo River until the water would not flow.", idiomatic: "Jing's army routed in chaos, hurling themselves into the Wo River until the water stopped flowing." },
  { zh: "景與腹心數騎自硤石濟淮，稍收散卒，得步騎八百人，南過小城，人登陴詬之曰：「跛奴！", literal: "Jing with a few trusted horsemen crossed the Huai at Xiashi, gradually gathered scattered troops, and got eight hundred foot and horse; passing a small town southward, men mounted the walls and reviled him: \"Cripple!", idiomatic: "Jing fled across the Huai at Xiashi with a handful of trusted riders, gathered scattered troops until he had eight hundred foot and horse, and passed a small town where men on the walls shouted: \"Cripple!" },
  { zh: "欲何為邪！", literal: "\"What do you think you're doing!\"", idiomatic: "\"What do you think you're doing!\"" },
  { zh: "」景怒，破城，殺詬者而去。", literal: "\" Jing in anger stormed the town, killed the revilers, and left.", idiomatic: "\" Jing in rage stormed the town, killed the revilers, and left." },
  { zh: "晝夜兼行，追軍不敢逼。", literal: "Marching day and night together, the pursuing army did not dare press close.", idiomatic: "He marched day and night; the pursuers did not dare press close." },
  { zh: "使謂紹宗曰：「景若就擒，公復何用！", literal: "He sent word to Shaozong: \"If Jing is captured, of what use will you be!", idiomatic: "He sent word to Shaozong: \"If Jing is taken, what use are you then!" },
  { zh: "」紹宗乃縱之。", literal: "\" Shaozong then let him go.", idiomatic: "\" Shaozong then let him go." },
  { zh: "辛丑，以尚書僕射謝舉為尚書令，守吏部尚書王克為僕射。", literal: "On xinchou, Vice Minister of the Masters of Writing Xie Ju was made Minister of the Masters of Writing, and Acting Minister of Personnel Wang Ke was made Vice Minister.", idiomatic: "On xinchou, vice minister Xie Ju was made minister of the Masters of Writing, and acting minister of personnel Wang Ke was made vice minister." },
  { zh: "甲辰，豫州刺史羊鴉仁以東魏軍漸逼，稱糧運不繼，棄懸瓠，還義陽；", literal: "On jiachen, Yuzhou Inspector Yang Yaren, as Eastern Wei armies pressed nearer, claimed grain transport could not keep up, abandoned Xuanhuo, and returned to Yiyang;", idiomatic: "On jiachen, Yuzhou inspector Yang Yaren, as Eastern Wei armies closed in, claimed his grain lines were failing, abandoned Xuanhuo, and withdrew to Yiyang;" },
  { zh: "殷州刺史羊思達亦棄項城走；", literal: "Yinzhou Inspector Yang Sida also abandoned Xiangcheng and fled;", idiomatic: "Yinzhou inspector Yang Sida also abandoned Xiangcheng and fled;" },
  { zh: "東魏人皆據之。", literal: "Eastern Wei men all seized them.", idiomatic: "Eastern Wei forces took both cities." },
  { zh: "上怒，責讓鴉仁。", literal: "The emperor was angry and rebuked Yaren.", idiomatic: "The emperor was furious and rebuked Yaren." },
  { zh: "鴉仁懼，啟申後期，頓軍淮上。", literal: "Yaren feared and memorialized asking delay; he halted his army on the Huai.", idiomatic: "Yaren, afraid, asked for more time and halted his army on the Huai." },
  { zh: "侯景既敗，不知所適，時鄱陽王范除南豫州刺史，未至。", literal: "Hou Jing having been defeated, did not know where to go; at the time Prince of Poyang Fan had been appointed Southern Yuzhou Inspector but had not yet arrived.", idiomatic: "Hou Jing, defeated, did not know where to turn. Prince Fan of Poyang had been appointed Southern Yuzhou inspector but had not yet arrived." },
  { zh: "馬頭戍主劉神茂，素為監州事韋黯所不容，聞景至，故往候之，景問曰：「壽陽去此不遠，城池險固，欲往投之，韋黯其納我乎？", literal: "Matou Garrison Commander Liu Shenmao had long been ill tolerated by Acting Inspector Wei An; hearing Jing had come, he therefore went to meet him. Jing asked: \"Shouchun is not far from here, its walls strong and secure—I wish to go throw myself on it; will Wei An admit me?", idiomatic: "Matou garrison commander Liu Shenmao had long been at odds with acting inspector Wei An. Hearing Jing was near, he went to meet him. Jing asked: \"Shouchun is close, its walls strong—I mean to throw myself on it. Will Wei An take me in?" },
  { zh: "」神茂曰：「黯雖據城，是監州耳。", literal: "\" Shenmao said: \"Though An holds the city, he is only acting inspector.", idiomatic: "\" Shenmao said: \"An holds the city, but he is only acting inspector." },
  { zh: "王若馳至近郊，彼必出迎，因而執之，可以集事。", literal: "\"If Your Highness gallops to the near suburbs, he is sure to come out to welcome you; seize him then and you can gather the affair.\"", idiomatic: "\"If Your Highness rides to the near suburbs, he will surely come out to welcome you. Seize him then and the thing is done.\"" },
  { zh: "得城之後，徐以啟聞，朝廷喜王南歸，必不責也。", literal: "\"After gaining the city, slowly report upward; the court will rejoice that Your Highness returns south and surely will not blame you.\"", idiomatic: "\"Once you hold the city, report upward at leisure. The court will rejoice at your return south and will not blame you.\"" },
  { zh: "」景執其手曰：「天教也！", literal: "\" Jing grasped his hand and said: \"Heaven teaches it!", idiomatic: "\" Jing grasped his hand and said: \"Heaven ordains it!" },
  { zh: "」神茂請帥步騎百人先為鄉導。", literal: "\" Shenmao asked to lead a hundred foot and horse ahead as guides.", idiomatic: "\" Shenmao asked to lead a hundred foot and horse ahead as guides." },
  { zh: "壬子，景夜至壽陽城下；", literal: "On renzi, Jing by night reached below Shouchun city;", idiomatic: "On renzi Jing reached Shouchun by night;" },
  { zh: "韋黯以為賊也，授甲登陴。", literal: "Wei An thought them bandits, issued armor, and mounted the walls.", idiomatic: "Wei An thought them bandits, issued armor, and manned the walls." },
  { zh: "景遣其徒告曰：「河南王戰敗來投此鎮，願速開門。", literal: "Jing sent his men to announce: \"The King of Henan, defeated in battle, comes to throw himself on this garrison—open the gates at once.", idiomatic: "Jing sent men to announce: \"The King of Henan, defeated, comes to this garrison—open the gates at once." },
  { zh: "」黯曰：「既不奉敕，不敢聞命。", literal: "\" An said: \"Having no imperial order, I dare not heed the command.", idiomatic: "\" An said: \"Without an imperial order I dare not obey." },
  { zh: "」景謂神茂曰：「事不諧矣。", literal: "\" Jing said to Shenmao: \"The affair will not succeed.", idiomatic: "\" Jing told Shenmao: \"The affair will not succeed." },
  { zh: "」神茂曰：「黯懦而寡智，可說下也。", literal: "\" Shenmao said: \"An is cowardly and short of wit—he can be talked down.", idiomatic: "\" Shenmao said: \"An is cowardly and witless. He can be talked down." },
  { zh: "」乃遣壽陽徐思玉入見黯曰：「河南王為朝廷所重，君所知也。", literal: "\" He then sent Shouchun's Xu Siyu in to see An and say: \"The King of Henan is weighty in the court's eyes, as you know.", idiomatic: "\" He sent Xu Siyu of Shouchun in to see An: \"The King of Henan carries weight at court, as you know." },
  { zh: "今失利來投，何得不受？", literal: "\"Now defeated and come to throw himself on you—how can you not receive him?\"", idiomatic: "\"Now he comes defeated—how can you refuse him?\"" },
  { zh: "」黯曰：「吾之受命，唯知守城；", literal: "\" An said: \"My commission is only to know how to hold the city;", idiomatic: "\" An said: \"My commission is only to hold the city;" },
  { zh: "河南自敗，何預吾事！", literal: "\"Henan defeated himself—what has that to do with me!\"", idiomatic: "\"Henan lost on his own—what is that to me!\"" },
  { zh: "」思玉曰：「國家付君以閫外之略，今君不肯開城，若魏追兵來至，河南為魏所殺，君豈能獨存！", literal: "\" Siyu said: \"The state entrusted you with authority beyond the passes; now you refuse to open the city—if Wei pursuers come and Henan is killed by Wei, can you alone survive!", idiomatic: "\" Siyu said: \"The state gave you authority beyond the passes. Refuse to open the gates, and when Wei pursuers come and Henan is killed, can you survive alone!" },
  { zh: "縱使或存，何顏以見朝廷？", literal: "\"Even if you somehow survive, with what face can you see the court?\"", idiomatic: "\"Even if you live, with what face will you see the court?\"" },
  { zh: "」黯然之。", literal: "\" An's color darkened.", idiomatic: "\" An's face fell." },
  { zh: "思玉出報，景大悅曰：「活我者，卿也！", literal: "Siyu came out and reported; Jing was greatly pleased and said: \"You are the one who saved my life!", idiomatic: "Siyu reported; Jing was delighted: \"You saved my life!" },
  { zh: "」癸丑，黯開門納景，景遣其將分守四門，詰責黯，將斬之；", literal: "\" On guichou, An opened the gates and admitted Jing; Jing sent his generals to guard the four gates, rebuked An, and was about to behead him;", idiomatic: "\" On guichou An opened the gates and admitted Jing. Jing posted generals at the four gates, rebuked An, and was about to behead him;" },
  { zh: "既而撫手大笑，置酒極歡。", literal: "then he clapped his hands, laughed greatly, and set out wine in extreme revelry.", idiomatic: "then he clapped his hands, laughed, and set out wine in great revelry." },
  { zh: "黯，睿之子也。", literal: "An was the son of Rui.", idiomatic: "An was the son of Wei Rui." },
  { zh: "朝廷聞景敗，未得審問；", literal: "The court heard Jing was defeated but could not yet verify the facts;", idiomatic: "The court heard Jing was defeated but could not yet verify it;" },
  { zh: "或云：「景與將士盡沒。", literal: "some said: \"Jing and his officers and soldiers are all destroyed.", idiomatic: "some said: \"Jing and all his officers and men are dead." },
  { zh: "」上下鹹以為憂。", literal: "\" High and low alike took it as cause for worry.", idiomatic: "\" Court and people alike grieved." },
  { zh: "侍中、太子詹事何敬容詣東宮，太子曰：「淮北始更有信，侯景定得身免，不如所傳。", literal: "Palace Attendant and Crown Prince Household Governor He Jingrong went to the Eastern Palace; the crown prince said: \"There is fresh word from north of the Huai—Hou Jing will surely escape with his life; it is not as reported.", idiomatic: "Palace attendant and crown prince household governor He Jingrong went to the Eastern Palace. The crown prince said: \"Fresh word from north of the Huai—Hou Jing will surely escape. It is not as reported." },
  { zh: "」敬容對曰：「得景遂死，深為朝廷之福。", literal: "\" Jingrong replied: \"If Jing were to die at once, that would be deep fortune for the court.", idiomatic: "\" Jingrong replied: \"If Jing died at once, that would be the court's great fortune." },
  { zh: "」太子失色，問其故，敬容曰：「景翻覆叛臣，終當亂國。", literal: "\" The crown prince changed color and asked the reason; Jingrong said: \"Jing is a turncoat rebel minister— in the end he will throw the state into chaos.", idiomatic: "\" The crown prince blanched and asked why. Jingrong said: \"Jing is a turncoat rebel—in the end he will ruin the realm." },
  { zh: "」太子於玄圃自講《老》、《莊》，敬容謂學士吳孜曰：「昔西晉祖尚玄虛，使中原淪於胡、羯。", literal: "\" The crown prince in the Mystic Garden lectured on the Laozi and Zhuangzi himself; Jingrong told Academician Wu Zi: \"In olden days Western Jin's founders honored empty mystery and let the central plains fall to Hu and Jie.", idiomatic: "\" The crown prince lectured on the Laozi and Zhuangzi in the Mystic Garden. Jingrong told academician Wu Zi: \"Western Jin's founders worshipped empty mystery and lost the central plains to the barbarians." },
  { zh: "今東宮復爾，江南亦將為戎乎！", literal: "\"Now the Eastern Palace does the same—will Jiangnan also become a land of war!\"", idiomatic: "\"Now the Eastern Palace does the same—will the south also become a battlefield!\"" },
  { zh: "甲寅，景遣儀同三司於子悅馳以敗聞，並自求貶削；", literal: "On jiayin, Jing sent Acting Three Excellencies Yu Ziyue in haste with news of defeat and himself asked to be demoted;", idiomatic: "On jiayin Jing sent Acting Three Excellencies Yu Ziyue in haste with news of defeat and asked to be demoted;" },
  { zh: "優詔不許。", literal: "a gracious edict refused.", idiomatic: "a gracious edict refused." },
  { zh: "景復求資給，上以景兵新破，未忍移易。", literal: "Jing again asked for supplies; the emperor, because Jing's army was newly broken, was unwilling to shift him.", idiomatic: "Jing again asked for supplies. The emperor, since Jing's army was freshly broken, would not move him." },
  { zh: "乙卯，即以景為南豫州牧，本官如故；", literal: "On yimao, Jing was immediately made Governor of Southern Yuzhou, his original posts as before;", idiomatic: "On yimao Jing was made governor of Southern Yuzhou, his original posts unchanged;" },
  { zh: "更以鄱陽王范為合州刺史，鎮合肥。", literal: "Prince of Poyang Fan was instead made Hezhou Inspector and garrisoned Hefei.", idiomatic: "Prince Fan of Poyang was made Hezhou inspector and garrisoned Hefei." },
  { zh: "光祿大夫蕭介上表諫曰：「竊聞侯景以渦陽敗績，隻馬歸命，陛下不悔前禍，復敕容納。", literal: "Supervisor of the Bright Hall Xiao Jie memorialized in remonstrance: \"I have heard that Hou Jing, defeated at Woyang, came back alone on horseback to submit his fate; Your Majesty did not regret the earlier disaster and again ordered him received.", idiomatic: "Supervisor of the Bright Hall Xiao Jie remonstrated: \"I hear Hou Jing, defeated at Woyang, came back alone to submit. Your Majesty did not regret the earlier disaster and received him again." },
  { zh: "臣聞凶人之性不移，天下之惡一也。", literal: "\"I have heard that the nature of a vicious man does not change—the evil under heaven is one.", idiomatic: "\"I hear the nature of a vicious man never changes—evil under heaven is one." },
  { zh: "昔呂布殺丁原以事董卓，終誅董而為賊；", literal: "\"In olden days Lü Bu killed Ding Yuan to serve Dong Zhuo, then killed Dong and became a bandit;", idiomatic: "\"Lü Bu killed Ding Yuan for Dong Zhuo, then killed Dong and became a bandit;" },
  { zh: "劉牢反王恭以歸晉，還背晉以構妖。", literal: "\"Liu Lao turned against Wang Gong to join Jin, then betrayed Jin to raise rebellion.", idiomatic: "\"Liu Lao turned on Wang Gong for Jin, then betrayed Jin and raised rebellion." },
  { zh: "何者？", literal: "\"Why is that?\"", idiomatic: "\"Why?\"" },
  { zh: "狼子野心，終無馴狎之性，養虎之喻，必見饑噬之禍。", literal: "\"A wolf cub's wild heart never knows tame nature; the parable of rearing a tiger ends in the hunger-bite disaster.", idiomatic: "\"A wolf cub's heart is never tame; feed a tiger and hunger will devour you." },
  { zh: "侯景以凶狡之才，荷高歡卵翼之遇，位忝台司，任居方伯，然而高歡墳土未干，即還反噬。", literal: "\"Hou Jing with vicious cunning talent received Gao Huan's brooding favor; his rank matched the Secretariat, his post was a regional lord—yet Gao Huan's grave earth was not dry before he turned to bite back.", idiomatic: "\"Hou Jing, vicious and cunning, owed Gao Huan brooding favor; he ranked with the Secretariat and ruled a region—yet before Gao Huan's grave was dry he turned to bite." },
  { zh: "逆力不逮，乃復逃死關西；", literal: "\"His rebellious strength did not reach—then he fled death to Guanxi;", idiomatic: "\"His rebellion failed—then he fled for his life to Guanxi;" },
  { zh: "宇文不容，故復投身於我。", literal: "\"the Yuwen would not tolerate him, so he threw himself on us again.", idiomatic: "\"the Yuwen would not have him, so he threw himself on us again." },
  { zh: "陛下前者所以不逆細流，正欲比屬國降胡以討匈奴，冀獲一戰之效耳；", literal: "\"Your Majesty earlier did not oppose the trickle, precisely wishing to compare subject-state surrendered Hu against the Xiongnu and hope for one battle's effect;", idiomatic: "\"Your Majesty earlier did not refuse the trickle, meaning to use a surrendered barbarian against the Xiongnu and win one battle;" },
  { zh: "今既亡師失地，直是境上之匹夫，陛下愛匹夫而棄與國，臣竊不取也。", literal: "\"now having lost army and territory he is plainly a man of the border—Your Majesty cherishes a common man and abandons the state allied with you; I privately think it unworthy.", idiomatic: "\"now he has lost army and land and is a border vagabond. Cherish him and abandon your ally—I think it unworthy." },
  { zh: "若國家猶待其更鳴之辰，歲暮之效，臣竊惟侯景必非歲暮之臣；", literal: "\"If the state still waits for his season of renewed song, his year's-end effect—I privately think Hou Jing will surely not be a year's-end minister;", idiomatic: "\"If the state waits for his late loyalty, I think Hou Jing will never be loyal in old age;" },
  { zh: "棄鄉國如脫屣，背君親如遺芥，豈知遠慕聖德，為江、淮之純臣乎！", literal: "\"abandoning home and state like casting off shoes, turning from lord and kin like dropping mustard—does he know to admire sage virtue from afar and be a pure minister of the Jiang and Huai!\"", idiomatic: "\"He casts off home like shoes and kin like mustard—does he mean to be a pure minister of the Jiang and Huai!\"" },
  { zh: "事跡顯然，無可致惑。", literal: "\"The facts are plain—no confusion need be invited.", idiomatic: "\"The facts are plain." },
  { zh: "臣朽老疾侵，不應干預朝政；", literal: "\"Your servant is decayed and old, disease encroaching—he should not interfere in court governance;", idiomatic: "\"I am old and ill and should not meddle in court affairs;" },
  { zh: "但楚囊將死，有城郢之忠，衛魚臨亡，亦有尸諫之節。", literal: "\"yet when the Chu satchel was about to die he had the loyalty of defending Ying; when the Wei fish faced death it also had the integrity of corpse-remonstrance.", idiomatic: "\"yet when the Chu satchel was dying he defended Ying; when the Wei fish faced death it remonstrated with its corpse." },
  { zh: "臣忝為宗室遺老，敢忘劉向之心！", literal: "\"Your servant, unworthy as a surviving elder of the imperial clan, dares not forget the heart of Liu Xiang!\"", idiomatic: "\"I, an unworthy surviving elder of the clan, dare not forget Liu Xiang's heart!\"" },
  { zh: "」上歎息其忠，然不能用。", literal: "\" The emperor sighed at his loyalty but could not employ the advice.", idiomatic: "\" The emperor sighed at his loyalty but would not follow it." },
  { zh: "介，思話之孫也。", literal: "Jie was the grandson of Sihua.", idiomatic: "Jie was the grandson of Xiao Sihua." },
  { zh: "己未，東魏大將軍澄朝於鄴。", literal: "On jiwei, Eastern Wei Grand General Cheng entered court at Ye.", idiomatic: "On jiwei Eastern Wei grand general Gao Cheng entered court at Ye." },
  { zh: "魏以開府儀同三司趙貴為司空。", literal: "Western Wei made Acting Three Excellencies Zhao Gui Minister of Works.", idiomatic: "Western Wei made Zhao Gui Minister of Works." },
  { zh: "魏皇孫生，大赦。", literal: "Western Wei's imperial grandson was born; general amnesty.", idiomatic: "A Western Wei imperial grandson was born; general amnesty." },
  { zh: "二月，東魏殺其南兗州刺史石長宣，討侯景之黨也；", literal: "In the second month, Eastern Wei killed its Southern Yanzhou Inspector Shi Changxuan, punishing Hou Jing's faction;", idiomatic: "In the second month Eastern Wei killed Southern Yanzhou inspector Shi Changxuan, punishing Hou Jing's faction;" },
  { zh: "其餘為景所脅從者，皆赦之。", literal: "the rest who had been coerced to follow Jing were all pardoned.", idiomatic: "the rest coerced to follow Jing were pardoned." },
  { zh: "東魏既得懸瓠、項城，悉復舊境。", literal: "Eastern Wei having taken Xuanhuo and Xiangcheng fully restored the old borders.", idiomatic: "Eastern Wei, having taken Xuanhuo and Xiangcheng, fully restored the old borders." },
  { zh: "大將軍澄數遣書移，復求通好；", literal: "Grand General Cheng repeatedly sent letters and proclamations again seeking renewed friendship;", idiomatic: "Grand General Gao Cheng repeatedly sent letters seeking renewed friendship;" },
  { zh: "朝廷未之許。", literal: "the court did not grant it.", idiomatic: "the court refused." },
  { zh: "澄謂貞陽侯淵明曰：「先王與梁主和好，十有餘年。", literal: "Cheng said to Marquis of Zhenyang Yuanming: \"The former king and the Liang ruler were at peace more than ten years.", idiomatic: "Gao Cheng told Marquis Xiao Yuanming of Zhenyang: \"The former king and the Liang ruler were at peace more than ten years." },
  { zh: "聞彼禮佛文云：『奉為魏主，並及先王。", literal: "\"I hear their Buddhist prayer text says: 'Offered for the Wei ruler, and for the former king as well.", idiomatic: "\"I hear their Buddhist prayer says: 'Offered for the Wei ruler and for the former king as well." },
  { zh: "』此乃梁主厚意；", literal: "' That is the Liang ruler's deep goodwill;", idiomatic: "' That is the Liang ruler's goodwill;" },
  { zh: "不謂一朝失信，致此紛擾，知非梁主本心，當是侯景扇動耳，宜遣使咨論。", literal: "\"I did not expect one morning's broken faith to bring this turmoil—I know it is not the Liang ruler's true heart; it must be Hou Jing's incitement. Envoys should be sent to consult.", idiomatic: "\"I did not expect faith broken overnight and this turmoil. I know it is not the Liang ruler's heart—it is Hou Jing's doing. Send envoys to consult." },
  { zh: "若梁主不忘舊好，吾亦不敢違先王之意，諸人並即遣還，侯景家屬亦當同遣。", literal: "\"If the Liang ruler does not forget the old friendship, I too dare not violate the former king's intent—all captives will be sent back at once, and Hou Jing's family as well.", idiomatic: "\"If the Liang ruler remembers old friendship, I dare not violate the former king's intent. All captives go back, and Hou Jing's family too." },
  { zh: "」淵明乃遣省事夏侯僧辯奉啟於上，稱「勃海王弘厚長者，若更通好，當聽淵明還。", literal: "\" Yuanming then sent Staff Officer Xiahou Sengbian with a memorial to the emperor, stating \"Prince of Bohai Hong is a generous elder—if friendship is renewed, Yuanming may return.", idiomatic: "\" Yuanming sent staff officer Xiahou Sengbian with a memorial: \"Prince Hong of Bohai is a generous elder. Renew friendship and Yuanming may return." },
  { zh: "」上得啟，流涕，與朝臣議之。", literal: "\" The emperor received the memorial, wept, and deliberated with the ministers.", idiomatic: "\" The emperor received it, wept, and debated with his ministers." },
  { zh: "右衛將軍朱異、御史中丞張綰等皆曰：「靜寇息民，和實為便。", literal: "Right Guard General Zhu Yi and Imperial Censor Zhang Chuo and others all said: \"Stilling bandits and resting the people—peace is truly convenient.", idiomatic: "Right Guard General Zhu Yi and imperial censor Zhang Chuo and others said: \"Still bandits and rest the people—peace is best." },
  { zh: "」司農卿傅岐獨曰：「高澄何事須和？", literal: "\" Minister of Finance Fu Qi alone said: \"Why would Gao Cheng need peace at all?", idiomatic: "\" Minister of Finance Fu Qi alone said: \"Why would Gao Cheng need peace?" },
  { zh: "必是設間，故命貞陽遣使，欲令侯景自疑。", literal: "\"It must be a stratagem to sow discord—therefore he ordered Zhenyang to send envoys, wishing to make Hou Jing suspect.", idiomatic: "\"It must be a stratagem. He ordered Zhenyang to send envoys to make Hou Jing suspicious." },
  { zh: "景意不安，必圖禍亂。", literal: "\"Jing's mind uneasy will surely plot disaster and chaos.", idiomatic: "\"Uneasy, Jing will plot disaster." },
  { zh: "若許通好，正墮其計中。", literal: "\"If peace is granted, you fall right into his scheme.", idiomatic: "\"Grant peace and you fall into his scheme." },
  { zh: "」異等固執宜和，上亦厭用兵，乃從異言，賜淵明書曰：「知高大將軍禮汝不薄，省啟，甚以慰懷。", literal: "\" Yi and the rest stubbornly held that peace was fitting; the emperor also wearied of war and followed Yi's words, bestowing on Yuanming a letter: \"Knowing Grand General Gao treats you not poorly—I have read your memorial and am much comforted.", idiomatic: "\" Yi and the rest insisted on peace; the emperor, weary of war, followed Yi and wrote Yuanming: \"I know Grand General Gao treats you well. Your memorial comforts me." },
  { zh: "當別遣行人，重敦鄰睦。", literal: "\"I shall separately send envoys to renew neighborly friendship.\"", idiomatic: "\"I shall send other envoys to renew neighborly friendship.\"" },
  { zh: "僧辯還，過壽陽，侯景竊訪知之，攝問，具服。", literal: "Sengbian returned, passed Shouchun; Hou Jing secretly learned of it, seized and interrogated him, and he confessed fully.", idiomatic: "Sengbian returned by way of Shouchun. Hou Jing learned of it secretly, seized and interrogated him, and he confessed." },
  { zh: "乃寫答淵明之書，陳啟於上曰：「高氏心懷鴆毒，怨盈北土，人願天從，歡身殞越。", literal: "Jing then copied a reply to Yuanming's letter and memorialized the emperor: \"The Gao house harbors poison in its heart, resentment fills the northern land; men's wishes and Heaven's will aligned—Huan's body perished.", idiomatic: "Jing copied a reply to Yuanming and memorialized: \"The Gao house harbors poison; the north seethes with resentment. Heaven answered men's wishes—Gao Huan is dead." },
  { zh: "子澄嗣惡，計滅待時，所以昧此一勝者，蓋大蕩澄心以盈凶毒耳。", literal: "\"Son Cheng inherits evil, plotting destruction while waiting his hour; the reason he glossed over this one victory is that he meant to cleanse Cheng's heart to fill his vicious poison.", idiomatic: "\"Son Cheng inherits evil and waits to destroy us. He glossed this victory only to cleanse his heart and fill his poison." },
  { zh: "澄苟行合天心，腹心無疾，又何急急奉璧求和？", literal: "\"If Cheng truly acted with Heaven's heart and had no sickness in his inner circle, why urgently offer jade and seek peace?", idiomatic: "\"If Cheng truly had Heaven's favor and no sickness within, why rush to offer jade and seek peace?" },
  { zh: "豈不以秦兵扼其喉，胡騎迫其背，故甘辭厚幣，取安大國。", literal: "\"Is it not because Qin troops choke his throat and Hu horse press his back—therefore sweet words and thick gifts to secure safety in a great state.", idiomatic: "\"Is it not because Qin troops choke his throat and Hu cavalry press his back—so sweet words and thick gifts buy safety in a great state?" },
  { zh: "臣聞『一日縱敵，數世之患』，何惜高澄一豎，以棄億兆之心！", literal: "\"Your servant has heard 'One day's loose enemy is generations' calamity'—why spare Gao Cheng, one boy, and abandon the hearts of hundreds of millions!\"", idiomatic: "\"I have heard: 'Loose the enemy one day, calamity for generations.' Why spare Gao Cheng, one boy, and abandon the hearts of the millions!\"" },
  { zh: "竊以北魏安強，莫過天監之始，鐘離之役，匹馬不歸。", literal: "\"I privately think Western Wei's strength and security never exceeded the start of Tianjian; at the battle of Zhongli not one horse returned.", idiomatic: "\"Western Wei's strength never exceeded Tianjian's start; at Zhongli not one horse returned." },
  { zh: "當其強也，陛下尚伐而取之；", literal: "\"When they were strong, Your Majesty still attacked and took from them;", idiomatic: "\"When they were strong, Your Majesty still attacked and took;" },
  { zh: "及其弱也，反慮而和之。", literal: "\"when they are weak, you instead worry and make peace.", idiomatic: "\"when they are weak, you worry and make peace." },
  { zh: "捨已成之功，縱垂死之虜，使其假命強梁，以遺後世，非直愚臣扼腕，實亦志士痛心。", literal: "\"Casting off achieved merit, loosing a dying captive, letting him borrow life and grow strong in Liang to bequeath to later ages—not only does this foolish minister wring his wrists; truly men of resolve are heart-sick.", idiomatic: "\"Cast off achieved merit, loose a dying captive, let him borrow life and grow strong to bequeath to later ages—not only does this fool wring his wrists; men of resolve are heart-sick." },
  { zh: "昔伍相奔吳，楚邦卒滅；", literal: "\"In olden days Minister Wu fled to Wu and the state of Chu was destroyed at last;", idiomatic: "\"Minister Wu fled to Wu and Chu was destroyed;" },
  { zh: "陳平去項，劉氏用興。", literal: "\"Chen Ping left Xiang and the house of Liu rose.", idiomatic: "\"Chen Ping left Xiang and Liu rose." },
  { zh: "臣雖才劣古人，心同往事。", literal: "\"Your servant's talent is inferior to the ancients, but his heart matches past affairs.", idiomatic: "\"My talent is less than the ancients', but my heart matches theirs." },
  { zh: "誠知高澄忌賈在翟，惡會居秦，求盟請和，冀除其患。", literal: "\"I truly know Gao Cheng hates Jia in Zhai and evil meeting in Qin—seeking alliance and peace, hoping to remove his trouble.", idiomatic: "\"I know Gao Cheng hates rivals in his house and foes abroad—he seeks alliance to remove trouble." },
  { zh: "若臣死有益，萬殞無辭。", literal: "\"If your servant's death would benefit, ten thousand deaths without refusal.", idiomatic: "\"If my death would help, ten thousand deaths without refusal." },
  { zh: "唯恐千載，有穢良史。", literal: "\"I only fear that after a thousand years there will stain on good history.", idiomatic: "\"I only fear a thousand years hence history will be stained." },
  { zh: "」景又致書於朱異，餉金三百兩；", literal: "\" Jing also sent a letter to Zhu Yi and presented three hundred taels of gold;", idiomatic: "\" Jing also sent Zhu Yi a letter and three hundred taels of gold;" },
  { zh: "異納金而不通其啟。", literal: "Yi accepted the gold but did not pass on his memorial.", idiomatic: "Yi took the gold but did not pass on his memorial." },
  { zh: "己卯，上遣使吊澄。", literal: "On jimao, the emperor sent envoys to condole Cheng.", idiomatic: "On jimao the emperor sent envoys to condole Gao Cheng." },
  { zh: "景又啟曰：「臣與高氏，釁隙已深，仰憑威靈，期雪仇恥；", literal: "Jing again memorialized: \"Your servant and the Gao house have rancor already deep; relying on Your Majesty's majesty, he hopes to wash away shame and vengeance;", idiomatic: "Jing memorialized again: \"I and the Gao house have deep rancor. Relying on Your Majesty's majesty I hope to wash away shame;" },
  { zh: "今陛下復與高氏連和，使臣何地自處！", literal: "\"now Your Majesty again joins with the Gao house—where can your servant place himself!\"", idiomatic: "\"now Your Majesty joins the Gao again—where can I stand!\"" },
  { zh: "乞申後戰，宣暢皇威！", literal: "\"I beg to defer further battle and spread imperial majesty!\"", idiomatic: "\"I beg defer further battle and spread imperial majesty!\"" },
  { zh: "」上報之曰：「朕與公大義已定，豈有成而相納，敗而相棄乎！", literal: "\" The emperor replied: \"My great principle with you is already fixed—how could there be accepting in success and abandoning in defeat!", idiomatic: "\" The emperor replied: \"Our great bond is fixed—how accept in success and abandon in defeat!" },
  { zh: "今高氏有使求和，朕亦更思偃武。", literal: "\"Now the Gao house has envoys seeking peace—I too again think to still arms.", idiomatic: "\"Now the Gao send envoys for peace—I too think to still arms." },
  { zh: "進退之宜，國有常制。", literal: "\"Advance and retreat have their proper measure—the state has constant rules.", idiomatic: "\"Advance and retreat have their rules." },
  { zh: "公但清靜自居，無勞慮也！", literal: "\"You need only dwell in quiet—no need for anxious thought!", idiomatic: "\"Dwell in quiet—do not worry!" },
  { zh: "」景又啟曰：「臣今蓄糧聚眾，秣馬潛戈，指日計期，克清趙、魏，不容軍出無名，故願以陛下為主耳。", literal: "\" Jing again memorialized: \"Your servant now stores grain and gathers masses, feeds horses and hides blades; counting days and fixing the term, he will clear Zhao and Wei; armies cannot march without name—therefore he wishes to take Your Majesty as lord.", idiomatic: "\" Jing memorialized again: \"I store grain, gather men, feed horses, hide blades. On the fixed day I will clear Zhao and Wei. Armies need a name—I wish to take Your Majesty as lord." },
  { zh: "今陛下棄臣遐外，南北復通，將恐微臣之身，不免高氏之手。", literal: "\"Now Your Majesty casts your servant far off, north and south join again—I fear your servant's slight person will not escape the Gao hand.", idiomatic: "\"Now you cast me far off while north and south join again—I fear I will not escape the Gao." },
  { zh: "」上又報曰：「朕為萬乘之主，豈可失信於一物！", literal: "\" The emperor again replied: \"I as lord of ten thousand chariots—how can I break faith over one thing!", idiomatic: "\" The emperor replied again: \"I am lord of ten thousand chariots—how break faith over one thing!" },
  { zh: "想公深得此心，不勞復有啟也。", literal: "\"I think you deeply grasp this heart—no need for further memorials.", idiomatic: "\"I think you grasp this—no more memorials needed." },
  { zh: "景乃詐為鄴中書，求以貞陽侯易景；", literal: "Jing then forged a letter from Ye and asked to exchange Marquis of Zhenyang for Jing;", idiomatic: "Jing forged a letter from Ye asking to exchange Marquis of Zhenyang for himself;" },
  { zh: "上將許之。", literal: "the emperor was about to grant it.", idiomatic: "the emperor was about to agree." },
  { zh: "舍人傅岐曰：「侯景以窮歸義，棄之不祥；", literal: "Attendant Fu Qi said: \"Hou Jing in extremity came in allegiance—to cast him off is ill fortune;", idiomatic: "Attendant Fu Qi said: \"Hou Jing came in allegiance at extremity—to cast him off is ill fortune;" },
  { zh: "且百戰之餘，寧肯束手受縶！", literal: "\"moreover after a hundred battles, would he willingly bind his hands and accept bonds!", idiomatic: "\"and after a hundred battles, would he bind his hands!" },
  { zh: "」謝舉、朱異曰：「景奔敗之將，一使之力耳。", literal: "\" Xie Ju and Zhu Yi said: \"Jing is a fleeing defeated general—one envoy's strength is enough.", idiomatic: "\" Xie Ju and Zhu Yi said: \"Jing is a fleeing defeated general—one envoy is enough." },
  { zh: "」上從之，復書曰：「貞陽旦至，侯景夕返。", literal: "\" The emperor followed them and replied: \"Zhenyang arrives at dawn, Hou Jing returns at dusk.", idiomatic: "\" The emperor agreed and replied: \"Zhenyang at dawn, Hou Jing at dusk." },
  { zh: "」景謂左右曰：「我固知吳老公薄心腸！", literal: "\" Jing told those beside him: \"I knew all along the old Wu lord has a thin heart!", idiomatic: "\" Jing told his men: \"I knew the old Wu lord has a thin heart!" },
  { zh: "」王偉說景曰：「今坐聽亦死，舉大事亦死，唯王圖之！", literal: "\" Wang Wei urged Jing: \"Now sit and listen—you die; raise a great affair—you die; only Your Highness must decide!", idiomatic: "\" Wang Wei urged Jing: \"Sit and listen—you die. Raise a great affair—you die. Only decide, Your Highness!" },
  { zh: "」於是始為反計，屬城居民，悉召募為軍士，輒停責市估及田租，百姓子女，悉以配將士。", literal: "\" Then he first formed plans of rebellion, calling up dependent-city residents as soldiers, halting market taxes and field rents, and assigning commoners' sons and daughters entirely to officers and soldiers.", idiomatic: "\" Then he began rebellion plans: conscripted dependent-city residents, halted market taxes and field rents, and assigned commoners' sons and daughters to officers." },
  { zh: "三月，癸巳，東魏以太尉襄城王旭為大司馬，開府儀同三司高岳為太尉。", literal: "In the third month, on guisi, Eastern Wei made Grand Commandant Prince of Xiangcheng Xu Grand Marshal and Acting Three Excellencies Gao Yue Grand Commandant.", idiomatic: "In the third month, on guisi, Eastern Wei made Grand Commandant Prince Xu of Xiangcheng grand marshal and Gao Yue grand commandant." },
  { zh: "辛亥，大將軍澄南臨黎陽，自虎牢濟河至洛陽。", literal: "On xinhai, Grand General Cheng went south to Lin Yang, crossed the Yellow River from Hulao, and reached Luoyang.", idiomatic: "On xinhai Grand General Gao Cheng went south to Lin Yang, crossed the Yellow River from Hulao, and reached Luoyang." },
  { zh: "魏同軌防長史裴寬與東魏將彭樂等戰，為樂所擒，澄禮遇甚厚，寬得間逃歸。", literal: "Western Wei Tonggui Defense Chief of Staff Pei Kuan fought Eastern Wei General Peng Yue and others, was captured by Yue; Cheng treated him with great honor and Pei Kuan found an opening and escaped back.", idiomatic: "Pei Kuan, Western Wei Tonggui defense chief of staff, fought Eastern Wei general Peng Yue, was captured; Gao Cheng honored him richly and Pei Kuan escaped." },
  { zh: "澄由太行返晉陽。", literal: "Cheng returned to Jinyang by the Taihang route.", idiomatic: "Gao Cheng returned to Jinyang by the Taihang route." },
  { zh: "屈獠洞斬李賁，傳首建康。", literal: "Quliao Cave beheaded Li Ben and sent the head to Jiankang.", idiomatic: "Quliao Cave beheaded Li Ben and sent the head to Jiankang." },
  { zh: "賁兄天寶遁入九真，收餘兵二萬圍愛州，交州司馬陳霸先帥眾討平之。", literal: "Ben's elder brother Tianbao fled into Jiuzhen, gathered remnant troops of twenty thousand, and besieged Aizhou; Jiaozhou Marshal Chen Baxian led troops and suppressed him.", idiomatic: "Ben's brother Tianbao fled to Jiuzhen, gathered twenty thousand remnant troops, and besieged Aizhou; Jiaozhou marshal Chen Baxian suppressed him." },
  { zh: "詔以霸先為西江督護、高要太守、督七郡諸軍事。", literal: "An edict made Baxian Protector of the Western River, Administrator of Gaoyao, and commander of military affairs in seven commanderies.", idiomatic: "An edict made Baxian Protector of the Western River, administrator of Gaoyao, and commander of military affairs in seven commanderies." },
  { zh: "夏，四月，甲子，東魏吏部令史張永和等偽假人官，事覺，糾檢、首者六萬餘人。", literal: "In summer, the fourth month, on jiazi, Eastern Wei Ministry of Personnel clerks Zhang Yonghe and others falsely assumed others' offices; the matter was exposed—those investigated and who informed numbered more than sixty thousand.", idiomatic: "In summer, the fourth month, on jiazi, Eastern Wei ministry of personnel clerks Zhang Yonghe and others forged appointments; exposed, those investigated and who informed exceeded sixty thousand." },
  { zh: "甲戌，東魏遣太尉高岳、行台慕容紹宗、大都督劉豐生等將步騎十萬攻魏王思政於穎川。", literal: "On jiaxu, Eastern Wei sent Grand Commandant Gao Yue, Field Secretariat Murong Shaozong, Grand Commander Liu Fengsheng, and others with a hundred thousand foot and horse to attack Western Wei's Wang Sizheng at Yingchuan.", idiomatic: "On jiaxu Eastern Wei sent Grand Commandant Gao Yue, field secretariat Murong Shaozong, grand commander Liu Fengsheng, and a hundred thousand foot and horse against Wang Sizheng at Yingchuan." },
  { zh: "思政命臥鼓偃旗，若無人者。", literal: "Sizheng ordered drums laid and banners lowered as if no one were there.", idiomatic: "Sizheng ordered drums laid and banners lowered as if empty." },
  { zh: "岳恃其眾，四面陵城。", literal: "Yue relied on his numbers and pressed the city on four sides.", idiomatic: "Yue relied on his numbers and pressed the city on four sides." },
  { zh: "思政選驍勇開門出戰，岳兵敗走。", literal: "Sizheng chose the fierce and brave, opened the gates, and went out to fight; Yue's army was defeated and fled.", idiomatic: "Sizheng chose the fierce, opened the gates, and fought; Yue's army fled." },
  { zh: "岳更築土山，晝夜攻之，思政隨方拒守，奪其土山，置樓堞以助防守。", literal: "Yue again built earthen hills and attacked day and night; Sizheng resisted on every side, seized their hills, and set parapets to aid defense.", idiomatic: "Yue built earthen hills and attacked day and night; Sizheng resisted, seized the hills, and set parapets." },
  { zh: "五月，魏以丞相泰為太師，廣陵王欣為太傅，李弼為大宗伯，趙貴為大司寇，於謹為大司空。", literal: "In the fifth month, Western Wei made Chancellor Tai Grand Preceptor, Prince of Guangling Xin Grand Tutor, Li Bi Grand Herald, Zhao Gui Grand Judge, and Yu Jin Grand Minister of Works.", idiomatic: "In the fifth month Western Wei made Yuwen Tai Grand Preceptor, Prince Xin of Guangling Grand Tutor, Li Bi Grand Herald, Zhao Gui Grand Judge, and Yu Jin Grand Minister of Works." },
  { zh: "太師泰奉太子巡撫西境，登隴，至原州，歷北長城，東趣五原，至蒲州，聞魏主不豫而還。", literal: "Grand Preceptor Tai accompanied the crown prince on a tour of the western marches, ascended Long, reached Yuanzhou, passed the northern Long Wall, turned east toward Wuyuan, reached Puzhou, heard the Wei ruler was unwell and returned.", idiomatic: "Grand Preceptor Yuwen Tai toured the western marches with the crown prince, ascended Long, reached Yuanzhou, passed the northern Long Wall, turned east to Wuyuan, reached Puzhou, heard the Wei ruler was ill and returned." },
  { zh: "及至，已癒，泰還華州。", literal: "When he arrived, the ruler had recovered; Tai returned to Huazhou.", idiomatic: "When he arrived the ruler had recovered; Yuwen Tai returned to Huazhou." },
  { zh: "上遣建康令謝挺、散騎常侍徐陵等聘於東魏，復修前好。", literal: "The emperor sent Jiankang Magistrate Xie Ting, Palace Attendant Xu Ling, and others on a friendly mission to Eastern Wei, renewing the former friendship.", idiomatic: "The emperor sent Jiankang magistrate Xie Ting, palace attendant Xu Ling, and others to Eastern Wei to renew friendship." },
  { zh: "陵，手離之子也。", literal: "Ling was the son of Shouli.", idiomatic: "Ling was the son of Xu Shouli." },
  { zh: "六月，東魏大將軍澄巡北邊。", literal: "In the sixth month, Eastern Wei Grand General Cheng toured the northern border.", idiomatic: "In the sixth month Eastern Wei grand general Gao Cheng toured the northern border." },
  { zh: "秋，七月，庚寅朔，日有食之。", literal: "In autumn, the seventh month, on the first day gengyin, there was an eclipse of the sun.", idiomatic: "In autumn, the seventh month, on new year's day gengyin, the sun was eclipsed." },
  { zh: "乙卯，東魏大將軍澄朝於鄴。", literal: "On yimao, Eastern Wei Grand General Cheng entered court at Ye.", idiomatic: "On yimao Eastern Wei grand general Gao Cheng entered court at Ye." },
  { zh: "以道士多偽濫，始罷南郊道壇。", literal: "Because Daoist priests were mostly false and corrupt, the southern suburb Daoist altar was first abolished.", idiomatic: "Because Daoist priests were mostly false, the southern suburb Daoist altar was abolished." },
  { zh: "八月，庚寅，澄還晉陽，遣尚書辛術帥諸將略江、淮之北，凡獲二十三州。", literal: "In the eighth month, on gengyin, Cheng returned to Jinyang and sent Minister of the Masters of Writing Xin Shu with generals to raid north of the Jiang and Huai—twenty-three provinces were taken in all.", idiomatic: "In the eighth month, on gengyin, Gao Cheng returned to Jinyang and sent minister Xin Shu with generals to raid north of the Jiang and Huai—twenty-three provinces in all." },
  { zh: "侯景自至壽陽，徵求無已，朝廷未嘗拒絕。", literal: "From the time Hou Jing reached Shouchun, his demands were endless and the court never refused.", idiomatic: "From the time Hou Jing reached Shouchun his demands were endless and the court never refused." },
  { zh: "景請娶於王、謝，上曰：「王、謝門高非偶，可於朱、張以下訪之。", literal: "Jing asked to marry into the Wang and Xie clans; the emperor said: \"The Wang and Xie gates are too high—not a match; you may inquire below the Zhu and Zhang.", idiomatic: "Jing asked to marry into the Wang and Xie clans. The emperor said: \"Wang and Xie are too lofty a match. Look below Zhu and Zhang." },
  { zh: "」景恚曰：「會將吳兒女配奴！", literal: "\" Jing said in rage: \"I will yet mate Wu girls to slaves!", idiomatic: "\" Jing raged: \"I will mate Wu girls to slaves!" },
  { zh: "」又啟求錦萬匹為軍人作袍，中領軍朱異議以青布給之。", literal: "\" He again memorialized asking for ten thousand lengths of brocade to make robes for soldiers; Central Palace Guard Commander Zhu Yi deliberated giving green cloth instead.", idiomatic: "\" He asked for ten thousand lengths of brocade for soldiers' robes; Central Palace Guard Commander Zhu Yi proposed green cloth instead." },
  { zh: "又以台所給仗多不能精，啟請東冶鍛工，欲更營造，敕並給之。", literal: "Also because many of the arms given from the capital were not fine, he memorialized asking for Eastern Forge smiths to rebuild them—an edict granted all.", idiomatic: "Because many arms from the capital were poor, he asked for Eastern Forge smiths to rebuild them—an edict granted all." },
  { zh: "景以安北將軍夏侯夔之子譒為長史，徐思玉為司馬，譒遂去「夏」稱「侯」，托為族子。", literal: "Jing made Northern Pacification General Xiahou Kui's son Zi chief of staff and Xu Siyu marshal; Zi then dropped Xia and called himself Hou, claiming to be a clan nephew.", idiomatic: "Jing made Northern Pacification General Xiahou Kui's son Zi chief of staff and Xu Siyu marshal. Zi dropped Xia, called himself Hou, and claimed to be a clan nephew." },
  { zh: "上既不用景言，與東魏和親，是後景表疏稍稍悖慢；", literal: "The emperor having not followed Jing's words and having made peace with Eastern Wei, thereafter Jing's memorials gradually grew insolent;", idiomatic: "The emperor having ignored Jing and made peace with Eastern Wei, Jing's memorials grew insolent;" },
  { zh: "又聞徐陵等使魏，反謀益甚。", literal: "hearing Xu Ling and others were envoys to Wei, his rebel plotting grew all the more.", idiomatic: "hearing Xu Ling was envoy to Wei, his plotting grew worse." },
  { zh: "元貞知景有異志，累啟還朝。", literal: "Yuan Zhen knew Jing had a different intent and repeatedly memorialized to return to court.", idiomatic: "Yuan Zhen knew Jing had other designs and repeatedly asked to return to court." },
  { zh: "景謂曰：「河北事雖不果，江南何慮失之，何不小忍！", literal: "Jing said to him: \"Though the Hebei affair did not succeed, what worry is there of losing Jiangnan—why not bear a little!", idiomatic: "Jing told him: \"Hebei failed, but what worry is Jiangnan—why not bear a little!" },
  { zh: "」貞懼，逃歸建康，具以事聞；", literal: "\" Zhen feared, fled back to Jiankang, and fully reported the matter;", idiomatic: "\" Zhen, afraid, fled to Jiankang and reported everything;" },
  { zh: "上以貞為始興內史，亦不問景。", literal: "the emperor made Zhen Administrator of Shixing and also did not question Jing.", idiomatic: "the emperor made Zhen administrator of Shixing and did not question Jing." },
  { zh: "臨賀王正德，所至貪暴不法，屢得罪於上，由是憤恨，陰養死士，儲米積貨，幸國家有變；", literal: "Prince of Linhe Zhengde, wherever he went was greedy, violent, and lawless; he repeatedly offended the emperor and therefore nursed resentment, secretly keeping death-dealing men, storing rice and piling goods, hoping the state would have change;", idiomatic: "Prince Zhengde of Linhe was greedy and lawless wherever he went, repeatedly offended the emperor, nursed resentment, secretly kept death-dealing men, stored grain and goods, and hoped for upheaval;" },
  { zh: "景知之。", literal: "Jing knew it.", idiomatic: "Jing knew." },
  { zh: "正德在北與徐思玉相知，景遣思玉致箋於正德曰：「今天子年尊，奸臣亂國。", literal: "Zhengde in the north had known Xu Siyu; Jing sent Siyu with a letter to Zhengde: \"Today the Son of Heaven is aged and wicked ministers throw the state into chaos.", idiomatic: "Zhengde had known Xu Siyu in the north. Jing sent Siyu with a letter: \"The Son of Heaven is aged and wicked ministers ruin the realm." },
  { zh: "以景觀之，計日禍敗。", literal: "\"In Jing's view, disaster and defeat are counted by days.", idiomatic: "\"In my view disaster comes within days." },
  { zh: "大王屬當儲貳，中被廢黜，四海業業，歸心大王。", literal: "\"Your Highness by right should be heir apparent, yet was deposed mid-course; the four seas tremble and hearts turn to Your Highness.", idiomatic: "\"You should be heir yet were deposed; the realm trembles and hearts turn to you." },
  { zh: "景雖不敏，實思自效。", literal: "\"Though Jing is not clever, he truly wishes to offer himself.", idiomatic: "\"I am not clever, but I wish to serve." },
  { zh: "願王允副蒼生，鑒斯誠款！", literal: "\"May Your Highness grant the people's wish and discern this sincere pledge!\"", idiomatic: "\"Grant the people's wish and see my sincerity!\"" },
  { zh: "」正德大喜曰：「侯公之意，暗與吾同，天授我也！", literal: "\" Zhengde was greatly pleased and said: \"Lord Hou's intent secretly matches mine—Heaven grants it!", idiomatic: "\" Zhengde was delighted: \"Lord Hou's heart matches mine in secret—Heaven grants it!" },
  { zh: "」報之曰：「朝廷之事，如公所言。", literal: "\" He replied: \"Court affairs are as you say.", idiomatic: "\" He replied: \"Court affairs are as you say." },
  { zh: "僕之有心，為日久矣。", literal: "\"Your servant's intent has been long.", idiomatic: "\"My intent is old." },
  { zh: "今僕為其內，公為其外，何有不濟！", literal: "\"Now your servant within, you without—what could fail!\"", idiomatic: "\"I within, you without—what could fail!\"" },
  { zh: "機事在速，今其時矣。", literal: "\"The critical affair lies in speed—now is the hour.", idiomatic: "\"Speed is everything—now is the hour." },
  { zh: "鄱陽王范密啟景謀反。", literal: "Prince of Poyang Fan secretly memorialized that Jing plotted rebellion.", idiomatic: "Prince Fan of Poyang secretly reported Jing's rebellion." },
  { zh: "時上以邊事專委朱異，動靜皆關之，異以為必無此理。", literal: "At the time the emperor had wholly entrusted border affairs to Zhu Yi; every move passed through him; Yi thought it surely could not be.", idiomatic: "The emperor had wholly entrusted border affairs to Zhu Yi; Yi thought it impossible." },
  { zh: "上報范曰：「景孤危寄命，譬如嬰兒仰人乳哺，以此事勢，安能反乎！", literal: "The emperor replied to Fan: \"Jing is isolated and perilous, his life entrusted elsewhere—like an infant looking up for another's milk; with this situation, how could he rebel!", idiomatic: "The emperor replied: \"Jing is isolated, his life in others' hands—like an infant at the breast. How could he rebel!" },
  { zh: "」范重陳之曰：「不早剪撲，禍及生民。", literal: "\" Fan again stated it: \"If not cut down early, calamity will reach the living people.", idiomatic: "\" Fan pressed: \"Fail to cut him down early and the people will suffer." },
  { zh: "」上曰：「朝廷自有處分，不須汝深憂也。", literal: "\" The emperor said: \"The court has its own disposition—no need for your deep worry.", idiomatic: "\" The emperor said: \"The court will handle it—no need for deep worry." },
  { zh: "」范復請自以合肥之眾討之，上不許。", literal: "\" Fan again asked to lead the Hefei forces himself to suppress him; the emperor did not permit.", idiomatic: "\" Fan asked to lead Hefei's forces himself; the emperor refused." },
  { zh: "朱異謂范使曰：「鄱陽王遂不許朝廷有一客！", literal: "Zhu Yi told Fan's messenger: \"Does Prince of Poyang not even allow the court one guest!", idiomatic: "Zhu Yi told Fan's messenger: \"Will Prince of Poyang not even leave the court one guest!" },
  { zh: "」自是范啟，異不復為通。", literal: "\" From then Fan's memorials Yi no longer passed through.", idiomatic: "\" From then Fan's memorials Yi no longer forwarded." },
  { zh: "景邀羊鴉仁同反，鴉仁執其使以聞。", literal: "Jing invited Yang Yaren to rebel together; Yaren seized his messenger and reported.", idiomatic: "Jing invited Yang Yaren to rebel; Yaren seized the messenger and reported." },
  { zh: "異曰：「景數百叛虜，何能為！", literal: "Yi said: \"Jing is a few hundred rebel captives—what can he do!", idiomatic: "Yi said: \"Jing is a few hundred rebel captives—what can he do!" },
  { zh: "」敕以使者付建康獄，俄解遣之。", literal: "\" An edict handed the messenger to Jiankang prison; soon he was released and sent away.", idiomatic: "\" An edict put the messenger in Jiankang prison; soon he was released." },
  { zh: "景益無所憚，啟上曰：「若臣事是實，應罹國憲；", literal: "Jing grew all the more unrestrained and memorialized the emperor: \"If your servant's affair is true, he should suffer the state's punishment;", idiomatic: "Jing grew bolder and memorialized: \"If I am guilty, let me suffer the state's law;" },
  { zh: "如蒙照察，請戮鴉仁！", literal: "\"if I receive your gracious scrutiny, I ask to execute Yaren!", idiomatic: "\"if you investigate graciously, execute Yaren!" },
  { zh: "」景又上言：「高澄狡猾，寧可全信！", literal: "\" Jing again memorialized: \"Gao Cheng is crafty—how can he be wholly trusted!", idiomatic: "\" Jing memorialized again: \"Gao Cheng is crafty—how trust him wholly!" },
  { zh: "陛下納其詭語，求與連和，臣亦竊所笑也。", literal: "Your Majesty accepts his deceitful words and seeks alliance with him—your servant too privately laughs at this.", idiomatic: "Your Majesty accepts his deceitful words and seeks alliance with him—I too have been privately laughing at this." },
  { zh: "臣寧堪粉骨，投命仇門，乞江西一境，受臣控督。", literal: "Your servant would rather be ground to bone powder and throw his life at the enemy's gate, begging one region west of the river under my control and supervision.", idiomatic: "Your servant would rather be ground to powder and throw his life at the enemy's gate—grant me one region west of the river to hold and govern." },
  { zh: "如其不許，即帥甲騎，臨江上，向閩、越。", literal: "If this is not granted, I shall then lead armored cavalry to the river's edge and march toward Min and Yue.", idiomatic: "If this is not granted, I shall lead armored cavalry to the river's edge and march toward Min and Yue." },
  { zh: "非唯朝廷自恥，亦是三公旰食。", literal: "Not only would the court be shamed, but the Three Dukes would eat late at their meals.", idiomatic: "The court would be shamed, and the Three Dukes would lose their sleep over it." },
  { zh: "」上使朱異宣語答景使曰：「譬如貧家，畜十客、五客，尚能得意；", literal: "\" The emperor had Zhu Yi deliver a proclamation answering Jing's envoy: \"It is like a poor household keeping ten or five guests and still being satisfied;", idiomatic: "\" The Liang emperor had Zhu Yi deliver a proclamation answering Hou Jing's envoy: \"It is like a poor household keeping ten or five guests and still being satisfied;" },
  { zh: "朕唯有一客，致有忿言，亦朕之失也。", literal: "I have only one guest, yet there are angry words—this too is my failing.", idiomatic: "I have only one guest, yet there are angry words—this too is my failing." },
  { zh: "」益加賞賜錦彩錢布，信使相望。", literal: "\" He increased gifts of brocade, silk, money, and cloth; envoys came and went in sight of one another.", idiomatic: "\" He increased gifts of brocade, silk, money, and cloth; envoys came and went without pause." },
  { zh: "戊戌，景反於壽陽，以誅中領軍朱異、少府卿徐驎、太子右衛率陸驗、制局監周石珍為名。", literal: "On wuxu, Jing rebelled at Shouyang, naming as his cause the execution of Central Army Commander Zhu Yi, Minister of the Palace Treasury Xu Lin, Right Commandant of the Crown Prince's Guard Lu Yan, and Director of the Bureau of Manufactures Zhou Shizhen.", idiomatic: "On wuxu, Hou Jing rebelled at Shouyang, naming as his cause the execution of Central Army Commander Zhu Yi, Minister of the Palace Treasury Xu Lin, Right Commandant of the Crown Prince's Guard Lu Yan, and Director of the Bureau of Manufactures Zhou Shizhen." },
  { zh: "異等皆以奸佞驕貪，蔽主弄權，為時人所疾，故景托以興兵。", literal: "Yi and the others were all hated by the age for flattery, arrogance, and greed—screening the ruler and manipulating power—so Jing used them as a pretext for raising troops.", idiomatic: "Yi and the others were hated throughout the realm for flattery, arrogance, and greed—screening the ruler and manipulating power—so Hou Jing used them as a pretext for raising troops." },
  { zh: "驎、驗，吳郡人；", literal: "Lin and Yan were from Wu commandery.", idiomatic: "Lin and Yan were from Wu commandery." },
  { zh: "石珍，丹楊人。", literal: "Shizhen was from Danyang.", idiomatic: "Shizhen was from Danyang." },
  { zh: "驎、驗迭為少府丞，以苛刻為務，百賈怨之，異尤與之暱，世人謂之「三蠹」。", literal: "Lin and Yan alternated as assistants in the Palace Treasury, making harshness their business; merchants hated them, Yi was especially intimate with them, and the world called them the Three Vermin.", idiomatic: "Lin and Yan alternated as assistants in the Palace Treasury, making harshness their business; merchants hated them, Zhu Yi was especially close to them, and the world called them the Three Vermin." },
  { zh: "司農卿傅岐，鯁直士也，嘗謂異曰：「卿任參國鈞，榮寵如此。", literal: "Minister of Agriculture Fu Qi was a stern, upright man; he once said to Yi, \"You share in governing the state and enjoy such honor and favor.", idiomatic: "Minister of Agriculture Fu Qi was a stern, upright man; he once said to Zhu Yi, \"You share in governing the state and enjoy such honor and favor." },
  { zh: "比日所聞，鄙穢狼藉，若使聖主發悟，欲免得乎！", literal: "What I have heard these last days is filth and disarray—if the sage ruler awakens, do you think you will escape punishment!", idiomatic: "What I have heard these last days is filth and disarray—if the sage ruler awakens, do you think you will escape punishment!" },
  { zh: "」異曰：「外間謗黷，知之久矣。", literal: "\" Yi said, \"Slander from outside—I have long known of it.", idiomatic: "\" Zhu Yi said, \"Slander from outside—I have long known of it." },
  { zh: "心苟無愧，何恤人言！", literal: "If the heart is without guilt, why fear men's words!", idiomatic: "If the heart is without guilt, why fear men's words!" },
  { zh: "」岐謂人曰：「朱彥和將死矣。", literal: "\" Fu Qi told others, \"Zhu Yanhe is about to die.", idiomatic: "\" Fu Qi told others, \"Zhu Yanhe is about to die." },
  { zh: "恃諂以求容，肆辯以拒諫，聞難而不懼，知惡而不改，天奪其鑒，其能久乎！", literal: "Relying on flattery to seek acceptance, unrestrained in argument to reject remonstrance—hearing difficulty without fear, knowing evil without change; Heaven has taken his mirror—how long can he last!", idiomatic: "Relying on flattery to seek acceptance, unrestrained in argument to reject remonstrance—hearing difficulty without fear, knowing evil without change; Heaven has taken his mirror—how long can he last!" },
  { zh: "景西攻馬頭，遣其將宋子仙東攻木柵，執戍主曹璆等，上聞之，笑曰：「是何能為！", literal: "Jing attacked Matao in the west and sent his general Song Zixian east to attack the wooden palisade, capturing garrison commanders including Cao Qiu; when the emperor heard, he laughed and said, \"What can they do!", idiomatic: "Hou Jing attacked Matao in the west and sent his general Song Zixian east to attack the wooden palisade, capturing garrison commanders including Cao Qiu; when the Liang emperor heard, he laughed and said, \"What can they do!" },
  { zh: "吾折棰笞之。", literal: "I shall break a rod and whip them.", idiomatic: "I'll break a rod and whip them." },
  { zh: "」敕購斬景者，封三千戶公，除州刺史。", literal: "\" He ordered that whoever killed Jing would be enfeoffed as a duke with three thousand households and made Inspector of Chu.", idiomatic: "\" He ordered that whoever killed Hou Jing would be enfeoffed as a duke with three thousand households and made Inspector of Chu." },
  { zh: "甲辰，詔以合州刺史鄱陽王范為南道都督，北徐州刺史封山侯正表為北道都督，司州刺史柳仲禮為西道都督，通直散騎常侍裴之高為東道都督，以侍中、開府儀同三司邵陵王綸持節董督眾軍以討景。", literal: "On jiachen, an edict made Hezhou Inspector Prince Fan of Poyang commander of the southern route, North Xuzhou Inspector Marquis Zhengbiao of Fengshan commander of the northern route, Si province Inspector Liu Zhongli commander of the western route, Direct Attendant Pei Zhigao commander of the eastern route, and Palace Attendant Prince Lun of Shaoling, holding imperial credentials, to oversee all forces against Jing.", idiomatic: "On jiachen, an edict made Hezhou Inspector Prince Fan of Poyang commander of the southern route, North Xuzhou Inspector Marquis Zhengbiao of Fengshan commander of the northern route, Si province Inspector Liu Zhongli commander of the western route, Direct Attendant Pei Zhigao commander of the eastern route, and Palace Attendant Prince Lun of Shaoling, holding imperial credentials, to oversee all forces against Hou Jing." },
  { zh: "正表，宏之子；", literal: "Zhengbiao was Hong's son.", idiomatic: "Zhengbiao was Hong's son." },
  { zh: "仲禮，慶遠之孫；", literal: "Zhongli was the grandson of Qingyuan.", idiomatic: "Zhongli was the grandson of Qingyuan." },
  { zh: "之高，邃之兄子也。", literal: "Zhigao was a nephew of Sui's elder brother.", idiomatic: "Zhigao was a nephew of Sui's elder brother." },
  { zh: "九月，東魏濮陽武公婁昭卒。", literal: "In the ninth month, Lou Zhao, Duke of Puyang of Eastern Wei, died.", idiomatic: "In the ninth month, Lou Zhao, Duke of Puyang of Eastern Wei, died." },
  { zh: "侯景聞台軍討之，問策於王偉。", literal: "When Hou Jing heard imperial troops were coming against him, he asked Wang Wei for counsel.", idiomatic: "When Hou Jing heard imperial troops were coming against him, he asked Wang Wei for counsel." },
  { zh: "偉曰：「邵陵若至，彼眾我寡，必為所困。", literal: "Wei said, \"If Prince Lun of Shaoling arrives, they will outnumber us—we are sure to be trapped.", idiomatic: "Wang Wei said, \"If Prince Lun of Shaoling arrives, they will outnumber us—we are sure to be trapped." },
  { zh: "不如棄淮南，決志東向，帥輕騎直掩建康；", literal: "Better abandon Huainan, resolve to turn east, lead light cavalry in a direct strike on Jiankang;", idiomatic: "Better abandon Huainan, resolve to turn east, and lead light cavalry in a direct strike on Jiankang;" },
  { zh: "臨賀反其內，大王攻其外，天下不足定也。", literal: "Prince Linhe rebels within, Your Highness attacks without—the realm is easily settled.", idiomatic: "Prince Linhe rebels within, Your Highness attacks without—the realm is easily settled." },
  { zh: "兵貴拙速，宜即進路。", literal: "Speed matters more than finesse in war; we should march at once.", idiomatic: "Speed matters more than finesse in war; we should march at once." },
  { zh: "」景乃留外弟中軍大都督王顯貴守壽陽；", literal: "\" Jing then left his maternal cousin, Central Army Grand Commander Wang Xiangui, to hold Shouyang;", idiomatic: "\" Hou Jing then left his maternal cousin, Central Army Grand Commander Wang Xiangui, to hold Shouyang;" },
  { zh: "癸未，詐稱遊獵，出壽陽，人不之覺。", literal: "on guimwei, feigning a hunting excursion, he left Shouyang without anyone noticing.", idiomatic: "on guimwei, feigning a hunting excursion, he left Shouyang without anyone noticing." },
  { zh: "冬，十月，庚寅，景揚聲趣合肥，而實襲譙州，助防董紹先開城降之。", literal: "In winter, the tenth month, on gengyin, Jing announced he was heading for Hefei but actually struck Qiao province; Assistant Defender Dong Shaoxian opened the gates and surrendered.", idiomatic: "In winter, the tenth month, on gengyin, Hou Jing announced he was heading for Hefei but actually struck Qiao province; Assistant Defender Dong Shaoxian opened the gates and surrendered." },
  { zh: "執刺史豐城侯泰。", literal: "They seized Inspector Marquis Tai of Fengcheng.", idiomatic: "They seized Inspector Marquis Tai of Fengcheng." },
  { zh: "泰，范之弟也，先為中書舍人，傾財以事時要，超授譙州刺史。", literal: "Tai was Fan's younger brother; formerly a Palace Secretary, he spent fortunes currying favor with powerful men and was abruptly made Inspector of Qiao.", idiomatic: "Tai was Fan's younger brother; formerly a Palace Secretary, he spent fortunes currying favor with powerful men and was abruptly made Inspector of Qiao." },
  { zh: "至州，遍發民丁，使擔腰輿、扇、繖等物，不限士庶；", literal: "On reaching his post, he conscripted men everywhere to carry palanquins, fans, parasols, and the like, with no distinction between gentry and commoners.", idiomatic: "On reaching his post, he conscripted men everywhere to carry palanquins, fans, parasols, and the like, with no distinction between gentry and commoners." },
  { zh: "恥為之者，重加杖責，多輸財者，即縱免之，由是人皆思亂。", literal: "Those who refused were harshly beaten; those who paid heavily were released—so everyone wished for disorder.", idiomatic: "Those who refused were harshly beaten; those who paid heavily were released—so everyone wished for disorder." },
  { zh: "及侯景至，人無戰心，故敗。", literal: "When Hou Jing arrived, no one would fight, and they were defeated.", idiomatic: "When Hou Jing arrived, no one would fight, and they were defeated." },
  { zh: "庚子，詔遣寧遠將軍王質帥眾三千巡江防遏。", literal: "On gengzi, an edict sent General Wang Zhi with three thousand men to patrol the river and block the advance.", idiomatic: "On gengzi, an edict sent General Wang Zhi with three thousand men to patrol the river and block the advance." },
  { zh: "景攻歷陽太守莊鐵，丁未，鐵以城降，因說景曰：「國家承平歲久，人不習戰，聞大王舉兵，內外震駭。", literal: "Jing attacked Liyang Administrator Zhuang Tie; on dingwei, Tie surrendered the city and urged Jing, saying, \"The state has been at peace so long that men no longer know war; when they hear Your Highness has raised arms, court and country alike are terrified.", idiomatic: "Hou Jing attacked Liyang Administrator Zhuang Tie; on dingwei, Tie surrendered the city and urged him, saying, \"The state has been at peace so long that men no longer know war; when they hear Your Highness has raised arms, court and country alike are terrified." },
  { zh: "宜乘此際速趨建康，可兵不血刃而成大功。", literal: "Seize this moment and rush on Jiankang—you can win a great victory without blood on the blades.", idiomatic: "Seize this moment and rush on Jiankang—you can win a great victory without blood on the blades." },
  { zh: "若使朝廷徐得為備，內外小安，遣羸兵千人直據採石，大王雖有精甲百萬，不得濟矣。", literal: "If the court slowly prepares, inner and outer calm return, and a thousand weak troops hold Caishi, Your Highness may have a million fine armored men and still not cross.", idiomatic: "If the court slowly prepares, inner and outer calm return, and a thousand weak troops hold Caishi, Your Highness may have a million fine armored men and still not cross." },
  { zh: "」景乃留儀同三司田英、郭駱守歷陽，以鐵為導，引兵臨江。", literal: "\" Jing then left Equal in Honor to the Three Dukes Tian Ying and Guo Luo to hold Liyang, made Tie his guide, and led his army to the river.", idiomatic: "\" Hou Jing then left Tian Ying and Guo Luo, Equal in Honor to the Three Dukes, to hold Liyang, made Tie his guide, and led his army to the river." },
  { zh: "江上鎮戍相次啟聞。", literal: "River garrisons sent reports one after another.", idiomatic: "River garrisons sent reports one after another." },
  { zh: "上問討景之策於都官尚書羊侃，侃請「以二千人急據採石，令邵陵王襲取壽陽；", literal: "The emperor asked Minister of Justice Yang Kan for a plan against Jing; Kan urged rushing two thousand men to hold Caishi and having Prince Lun of Shaoling strike Shouyang;", idiomatic: "The Liang emperor asked Minister of Justice Yang Kan for a plan against Hou Jing; Yang Kan urged rushing two thousand men to hold Caishi and having Prince Lun of Shaoling strike Shouyang;" },
  { zh: "使景進不得前，退失巢穴，烏合之眾，自然瓦解。", literal: "Jing could neither advance nor retreat to his lair; his rabble would collapse of itself.", idiomatic: "Hou Jing could neither advance nor retreat to his lair; his rabble would collapse of itself." },
  { zh: "」朱異曰：「景必無渡江之志。", literal: "\" Zhu Yi said, \"Jing surely has no intention of crossing the river.", idiomatic: "\" Zhu Yi said, \"Hou Jing surely has no intention of crossing the river." },
  { zh: "」遂寢其議。", literal: "\" The proposal was shelved.", idiomatic: "\" The proposal was shelved." },
  { zh: "侃曰：「今茲敗矣！", literal: "Kan said, \"We are defeated already!", idiomatic: "Yang Kan said, \"We are defeated already!" },
  { zh: "戊申，以臨賀王正德為平北將軍、都督京師諸軍事，屯丹楊郡。", literal: "On wushen, Prince Zhengde of Linhe was made General Who Pacifies the North and commander of capital forces, stationed in Danyang commandery.", idiomatic: "On wushen, Prince Zhengde of Linhe was made General Who Pacifies the North and commander of capital forces, stationed in Danyang commandery." },
  { zh: "正德遣大船數十艘，詐稱載荻，密以濟景。", literal: "Zhengde sent dozens of large ships, claiming they carried reeds, secretly to ferry Jing across.", idiomatic: "Zhengde sent dozens of large ships, claiming they carried reeds, secretly to ferry Hou Jing across." },
  { zh: "景將濟，慮王質為梗，使諜視之。", literal: "As Jing prepared to cross, fearing Wang Zhi would block him, he sent spies to watch.", idiomatic: "As Hou Jing prepared to cross, fearing Wang Zhi would block him, he sent spies to watch." },
  { zh: "會臨川大守陳昕啟稱：「採石急須重鎮，王質水軍輕弱，恐不能濟。", literal: "Just then Linchuan Administrator Chen Xin memorialized, saying, \"Caishi urgently needs a strong garrison; Wang Zhi's river forces are light and weak—they may not hold.", idiomatic: "Just then Linchuan Administrator Chen Xin memorialized, saying, \"Caishi urgently needs a strong garrison; Wang Zhi's river forces are light and weak—they may not hold." },
  { zh: "」上以昕為雲旗將軍，代質戍採石，征質知丹楊尹事。", literal: "\" The emperor made Xin General of the Cloud Banner, replaced Zhi at Caishi, and summoned Zhi to serve as Governor of Danyang.", idiomatic: "\" The Liang emperor made Xin General of the Cloud Banner, replaced Zhi at Caishi, and summoned Zhi to serve as Governor of Danyang." },
  { zh: "昕，慶之之子也。", literal: "Xin was the son of Qingzhi.", idiomatic: "Xin was the son of Qingzhi." },
  { zh: "質去採石，而昕猶未下渚。", literal: "Zhi left Caishi, but Xin had not yet descended to the landing.", idiomatic: "Zhi left Caishi, but Xin had not yet descended to the landing." },
  { zh: "諜告景云：「質已退。", literal: "Spies told Jing, \"Zhi has withdrawn.", idiomatic: "Spies told Hou Jing, \"Zhi has withdrawn." },
  { zh: "」景使折江東樹枝為驗，諜如言而返，景大喜曰：「吾事辦矣！", literal: "\" Jing had them break branches east of the river as proof; the spies returned as reported, and Jing rejoiced, saying, \"My plan is done!", idiomatic: "\" Hou Jing had them break branches east of the river as proof; the spies returned as reported, and he rejoiced, saying, \"My plan is done!" },
  { zh: "」己酉，自橫江濟於採石，有馬數百匹，兵八千人。", literal: "\" On jiyou he crossed from Hengjiang to Caishi with several hundred horses and eight thousand troops.", idiomatic: "\" On jiyou he crossed from Hengjiang to Caishi with several hundred horses and eight thousand troops." },
  { zh: "是夕，朝廷始命戒嚴。", literal: "That evening the court first ordered martial law.", idiomatic: "That evening the court first ordered martial law." },
  { zh: "景分兵襲姑孰，執淮南太守文成侯寧。", literal: "Jing divided his forces to seize Gushu and captured Huainan Administrator Marquis Ning of Wencheng.", idiomatic: "Hou Jing divided his forces to seize Gushu and captured Huainan Administrator Marquis Ning of Wencheng." },
  { zh: "南津校尉江子一帥舟師千餘人，欲於下流邀景；", literal: "South Ford Commandant Jiang Ziyi led more than a thousand river troops, intending to intercept Jing downstream;", idiomatic: "South Ford Commandant Jiang Ziyi led more than a thousand river troops, intending to intercept Hou Jing downstream;" },
  { zh: "其副董桃生，家在江北，與其徒先潰走。", literal: "his deputy Dong Taosheng, whose family was north of the river, fled first with his men.", idiomatic: "his deputy Dong Taosheng, whose family was north of the river, fled first with his men." },
  { zh: "子一收餘眾，步還建康。", literal: "Ziyi gathered the survivors and walked back to Jiankang.", idiomatic: "Ziyi gathered the survivors and walked back to Jiankang." },
  { zh: "子一，子四之兄也。", literal: "Ziyi was the elder brother of Zisi.", idiomatic: "Ziyi was the elder brother of Zisi." },
  { zh: "太子見事急，戎服入見上，稟受方略，上曰：「此自汝事，何更問為！", literal: "The crown prince, seeing crisis, entered in armor to ask the emperor for strategy; the emperor said, \"This is your affair—why ask further!", idiomatic: "The crown prince, seeing crisis, entered in armor to ask the Liang emperor for strategy; the emperor said, \"This is your affair—why ask further!" },
  { zh: "內外軍悉以付汝。", literal: "All inner and outer forces are entrusted to you.", idiomatic: "All inner and outer forces are entrusted to you." },
  { zh: "」太子乃停中書省，指授軍事，物情惶駭，莫有應募者。", literal: "\" The prince remained at the Secretariat directing military affairs; public fear ran wild, and none volunteered.", idiomatic: "\" The prince remained at the Secretariat directing military affairs; public fear ran wild, and none volunteered." },
  { zh: "朝廷猶不知臨賀王正德之情，命正德屯朱雀門，寧國公大臨屯新亭，太府卿韋黯屯六門，繕修宮城，為受敵之備。", literal: "The court still did not know Prince Zhengde of Linhe's treachery; Zhengde was ordered to hold the Vermilion Bird Gate, Duke Dalin of Ningguo to camp at Xinting, Palace Treasurer Wei An to hold the Six Gates; the palace walls were repaired against attack.", idiomatic: "The court still did not know Prince Zhengde of Linhe's treachery; Zhengde was ordered to hold the Vermilion Bird Gate, Duke Dalin of Ningguo to camp at Xinting, Palace Treasurer Wei An to hold the Six Gates; the palace walls were repaired against attack." },
  { zh: "大臨，大器之弟也。", literal: "Dalin was the younger brother of Daqi.", idiomatic: "Dalin was the younger brother of Daqi." },
  { zh: "己酉，景至慈湖。", literal: "On jiyou, Jing reached Cihu.", idiomatic: "On jiyou, Hou Jing reached Cihu." },
  { zh: "建康大駭，御街人更相劫掠，不復通行。", literal: "Jiankang was terrified; on the imperial avenue people robbed one another and passage ceased.", idiomatic: "Jiankang was terrified; on the imperial avenue people robbed one another and passage ceased." },
  { zh: "赦東、西冶、尚方錢署及建康系囚，以揚州刺史宣城王大器都督城內諸軍事，以羊侃為軍師將軍副之，南浦侯推守東府，西豐公大春守石頭，輕車長史謝禧、始興太守元貞守白下，韋黯與右衛將軍柳津等分守宮城諸門及朝堂。", literal: "Prisoners of the eastern and western foundries, the Directorate of Manufactures, the Money Office, and Jiankang jails were pardoned; Yangzhou Inspector Prince Daqi of Xuancheng was made commander of inner-city forces, with Yang Kan as Chief of Staff; Marquis Tui of Nanpu held the Eastern Palace, Duke Dachun of Xifeng held Shitou, Chief Clerk Xie Xi of the Light Chariots and Shixing Administrator Yuan Zhen held Baixia; Wei An and Right Guard General Liu Jin and others divided the palace gates and audience halls.", idiomatic: "Prisoners of the eastern and western foundries, the Directorate of Manufactures, the Money Office, and Jiankang jails were pardoned; Yangzhou Inspector Prince Daqi of Xuancheng was made commander of inner-city forces, with Yang Kan as Chief of Staff; Marquis Tui of Nanpu held the Eastern Palace, Duke Dachun of Xifeng held Shitou, Chief Clerk Xie Xi and Shixing Administrator Yuan Zhen held Baixia; Wei An and Right Guard General Liu Jin and others divided the palace gates and audience halls." },
  { zh: "推，秀之子；", literal: "Tui was Xiu's son.", idiomatic: "Tui was Xiu's son." },
  { zh: "大春，大臨之弟；", literal: "Dachun was Dalin's younger brother.", idiomatic: "Dachun was Dalin's younger brother." },
  { zh: "津，仲禮之父也。", literal: "Jin was Zhongli's father.", idiomatic: "Jin was Zhongli's father." },
  { zh: "擔諸寺庫公藏錢，聚之德陽堂，以充軍實。", literal: "Public funds from temple treasuries were gathered at the Hall of Virtue and Virtue to supply the army.", idiomatic: "Public funds from temple treasuries were gathered at the Hall of Virtue and Virtue to supply the army." },
  { zh: "庚戌，侯景至板橋，遣徐思玉來求見上，實欲觀城中虛實。", literal: "On gengxu, Hou Jing reached Banqiao and sent Xu Siyu to request an audience—actually to scout the city's strength.", idiomatic: "On gengxu, Hou Jing reached Banqiao and sent Xu Siyu to request an audience—actually to scout the city's strength." },
  { zh: "上召問之。", literal: "The emperor summoned and questioned him.", idiomatic: "The Liang emperor summoned and questioned him." },
  { zh: "思玉詐稱叛景請間陳事，上將屏左右，舍人高善寶曰：「思玉從賊中來，情偽難測，安可使獨在殿上！", literal: "Siyu feigned defection to speak privately; as the emperor was about to dismiss attendants, Registrar Gao Shanbao said, \"Siyu came from the rebels—his truth is hard to judge; how can he be left alone in the hall!", idiomatic: "Siyu feigned defection to speak privately; as the Liang emperor was about to dismiss attendants, Registrar Gao Shanbao said, \"Siyu came from the rebels—his truth is hard to judge; how can he be left alone in the hall!" },
  { zh: "」朱異侍坐，曰：「徐思玉豈刺客邪！", literal: "\" Zhu Yi, seated beside him, said, \"Is Xu Siyu an assassin!", idiomatic: "\" Zhu Yi, seated beside him, said, \"Is Xu Siyu an assassin!" },
  { zh: "」思玉出景啟，言「異等弄權，乞帶甲入朝，除君側之惡。", literal: "\" Siyu produced Jing's memorial, saying, \"Yi and the others manipulate power; I beg to enter court in armor and remove the evil at the ruler's side.", idiomatic: "\" Siyu produced Hou Jing's memorial, saying, \"Yi and the others manipulate power; I beg to enter court in armor and remove the evil at the ruler's side." },
  { zh: "」異甚慚悚。", literal: "\" Yi was deeply ashamed and alarmed.", idiomatic: "\" Zhu Yi was deeply ashamed and alarmed." },
  { zh: "景又請遣了事舍人出相領解，上遣中書舍人賀季、主書郭寶亮隨思玉勞景於板橋。", literal: "Jing also asked that a capable registrar be sent out to receive and explain; the emperor sent Palace Secretaries He Ji and Chief Clerk Guo Baoliang with Siyu to greet Jing at Banqiao.", idiomatic: "Hou Jing also asked that a capable registrar be sent out to receive and explain; the Liang emperor sent Palace Secretaries He Ji and Chief Clerk Guo Baoliang with Siyu to greet him at Banqiao." },
  { zh: "景北面受敕，季曰：「今者之舉何名？", literal: "Jing faced north to receive the edict; Ji said, \"What is the name of this present campaign?", idiomatic: "Hou Jing faced north to receive the edict; He Ji said, \"What is the name of this present campaign?" },
  { zh: "」景曰：「欲為帝也！", literal: "\" Jing said, \"I wish to be emperor!", idiomatic: "\" Hou Jing said, \"I wish to be emperor!" },
  { zh: "」王偉進曰：「朱異等亂政，除奸臣耳。", literal: "\" Wang Wei stepped forward and said, \"Zhu Yi and the others disorder government—merely to remove wicked ministers.", idiomatic: "\" Wang Wei stepped forward and said, \"Zhu Yi and the others disorder government—merely to remove wicked ministers." },
  { zh: "」景既出惡言，遂留季，獨遣寶亮還宮。", literal: "\" Jing having spoken evil words, he then detained Ji and sent only Baoliang back to the palace.", idiomatic: "\" Having spoken evil words, Hou Jing detained He Ji and sent only Guo Baoliang back to the palace." },
  { zh: "百姓聞景至，競入城，公私混亂，無復次第，羊侃區分防擬，皆以宗室間之。", literal: "When the people heard Jing had arrived, they rushed into the city; public and private affairs fell into chaos without order; Yang Kan organized defenses, placing members of the imperial clan between units.", idiomatic: "When the people heard Hou Jing had arrived, they rushed into the city; public and private affairs fell into chaos; Yang Kan organized defenses, placing members of the imperial clan between units." },
  { zh: "軍人爭入武庫，自取器甲，所司不能禁，侃命斬數人，方止。", literal: "Soldiers fought to enter the armory and take weapons and armor themselves; the officials could not stop them until Kan ordered several men beheaded.", idiomatic: "Soldiers fought to enter the armory and take weapons and armor themselves; the officials could not stop them until Yang Kan ordered several men beheaded." },
  { zh: "是時，梁興四十七年，境內無事，公卿在位及閭裡士大夫罕見兵甲，賊至猝迫，公私駭震。", literal: "At this time Liang had risen forty-seven years; within the borders all was calm; officials in office and gentry in the lanes rarely saw arms; when the rebels came suddenly, public and private were shaken with terror.", idiomatic: "Liang had risen forty-seven years; within the borders all was calm; officials and gentry rarely saw arms; when the rebels came suddenly, public and private were shaken with terror." },
  { zh: "宿將已盡，後進少年並出在外，軍旅指手為，一決於侃，侃膽力俱壯，太子深仗之。", literal: "Veteran generals were gone; younger successors were all abroad; the army looked to one man—Kan decided all; Kan's courage and strength were both great, and the prince relied deeply on him.", idiomatic: "Veteran generals were gone; younger successors were all abroad; the army looked to one man—Yang Kan decided all; his courage and strength were both great, and the prince relied deeply on him." },
  { zh: "辛亥，景至朱雀桁南，太子以臨賀王正德守宣陽門，東宮學士新野庾信守朱雀門，帥宮中文武三千餘人營桁北。", literal: "On xinhai, Jing reached the south of the Vermilion Bird Bridge; the prince set Prince Zhengde of Linhe to hold Xuanyang Gate, Eastern Palace scholar Yu Xin of Xinye to hold the Vermilion Bird Gate, and led more than three thousand civil and military men from the palace to camp north of the bridge.", idiomatic: "On xinhai, Hou Jing reached the south of the Vermilion Bird Bridge; the prince set Prince Zhengde of Linhe to hold Xuanyang Gate, Eastern Palace scholar Yu Xin of Xinye to hold the Vermilion Bird Gate, and led more than three thousand civil and military men from the palace to camp north of the bridge." },
  { zh: "太子命信開大桁以挫其鋒，正德曰：「百姓見開桁，必大驚駭。", literal: "The prince ordered Xin to open the great bridge to blunt the enemy's edge; Zhengde said, \"If the people see the bridge opened, they will be greatly terrified.", idiomatic: "The prince ordered Xin to open the great bridge to blunt the enemy's edge; Zhengde said, \"If the people see the bridge opened, they will be greatly terrified." },
  { zh: "可且安物情。", literal: "We may for now settle public feeling.", idiomatic: "We may for now settle public feeling." },
  { zh: "」太子從之。", literal: "\" The prince agreed.", idiomatic: "\" The prince agreed." },
  { zh: "俄而景至，信帥眾開桁，始除一舶。", literal: "Soon Jing arrived; Xin led his men to open the bridge, removing only one barge at first.", idiomatic: "Soon Hou Jing arrived; Xin led his men to open the bridge, removing only one barge at first." },
  { zh: "見景軍皆著鐵面，退隱於門。", literal: "Seeing Jing's troops all wore iron masks, he withdrew and hid behind the gate.", idiomatic: "Seeing Hou Jing's troops all wore iron masks, he withdrew and hid behind the gate." },
  { zh: "信方食甘蔗，有飛箭中門柱，信手甘蔗，應弦而落，遂棄軍走。", literal: "Xin was eating sugarcane when a flying arrow struck the gatepost; the cane fell from his hand at the twang of the bowstring, and he abandoned his troops and fled.", idiomatic: "Xin was eating sugarcane when a flying arrow struck the gatepost; the cane fell from his hand at the twang of the bowstring, and he abandoned his troops and fled." },
  { zh: "南塘遊軍沈子睦，臨賀王正德之黨也，復閉桁渡景。", literal: "Shen Zimu of the South Pond patrol, a partisan of Prince Zhengde of Linhe, closed the bridge again and ferried Jing across.", idiomatic: "Shen Zimu of the South Pond patrol, a partisan of Prince Zhengde of Linhe, closed the bridge again and ferried Hou Jing across." },
  { zh: "太子使王質將精兵三千援信，至領軍府，遇賊，未陳而走。", literal: "The prince sent Wang Zhi with three thousand picked troops to aid Xin; reaching the Commandant's headquarters, they met the rebels, formed no array, and fled.", idiomatic: "The prince sent Wang Zhi with three thousand picked troops to aid Xin; reaching the Commandant's headquarters, they met the rebels, formed no array, and fled." },
  { zh: "正德帥眾於張侯橋迎景，馬上交揖，既入宣陽門，望闕而拜，歔欷流涕，隨景渡淮。", literal: "Zhengde led his men to welcome Jing at Zhanghou Bridge, bowing from horseback; entering Xuanyang Gate, he looked toward the palace and bowed, weeping and sobbing, then followed Jing across the Huai.", idiomatic: "Zhengde led his men to welcome Hou Jing at Zhanghou Bridge, bowing from horseback; entering Xuanyang Gate, he looked toward the palace and bowed, weeping and sobbing, then followed him across the Huai." },
  { zh: "景軍皆著青袍，正德軍並著絳袍，碧裡，既與景合，悉反其袍。", literal: "Jing's troops all wore green robes; Zhengde's all wore crimson robes with green lining; once they joined Jing, all reversed their robes.", idiomatic: "Hou Jing's troops all wore green robes; Zhengde's all wore crimson robes with green lining; once they joined him, all reversed their robes." },
  { zh: "景乘勝至闕下，城中忷懼，羊侃詐稱得射書云：「邵陵王、西昌侯援兵已至近路。", literal: "Jing pressed his victory to the palace gates; the city was in uproar and fear; Yang Kan falsely claimed to have received a letter shot in, saying, \"Prince Lun of Shaoling and Marquis of Xichang—relief troops have reached the near road.", idiomatic: "Hou Jing pressed his victory to the palace gates; the city was in uproar and fear; Yang Kan falsely claimed to have received a letter shot in, saying, \"Prince Lun of Shaoling and Marquis of Xichang—relief troops have reached the near road." },
  { zh: "」眾乃少安。", literal: "\" The crowd was somewhat calmed.", idiomatic: "\" The crowd was somewhat calmed." },
  { zh: "西豐公大春棄石頭，奔京口；", literal: "Duke Dachun of Xifeng abandoned Shitou and fled to Jingkou;", idiomatic: "Duke Dachun of Xifeng abandoned Shitou and fled to Jingkou;" },
  { zh: "謝禧、元貞棄白下走；", literal: "Xie Xi and Yuan Zhen abandoned Baixia and fled;", idiomatic: "Xie Xi and Yuan Zhen abandoned Baixia and fled;" },
  { zh: "津主彭文粲等以石頭城降景，景遣其儀同三司於子悅守之。", literal: "Jin's commander Peng Wencan and others surrendered Shitou city to Jing; Jing sent his Equal in Honor to the Three Dukes Yu Ziyue to hold it.", idiomatic: "Liu Jin's commander Peng Wencan and others surrendered Shitou city to Hou Jing; he sent Yu Ziyue, Equal in Honor to the Three Dukes, to hold it." },
  { zh: "壬子，景列兵繞台城，幡旗皆黑，射啟於城中曰：「朱異等蔑弄朝權，輕作威福，臣為所陷，欲加屠戮。", literal: "On renzi, Jing arrayed troops around the capital enclosure; banners and flags were all black; he shot a memorial into the city, saying, \"Zhu Yi and the others scorn and manipulate court power, lightly wielding authority and favor; your servant was trapped by them and faces slaughter.", idiomatic: "On renzi, Hou Jing arrayed troops around the capital enclosure; banners and flags were all black; he shot a memorial into the city, saying, \"Zhu Yi and the others scorn and manipulate court power, lightly wielding authority and favor; your servant was trapped by them and faces slaughter." },
  { zh: "陛下若誅朱異等，臣則斂轡北歸。", literal: "If Your Majesty executes Zhu Yi and the others, your servant will gather reins and return north.", idiomatic: "If Your Majesty executes Zhu Yi and the others, your servant will gather reins and return north." },
  { zh: "」上問太子：「有是乎？", literal: "\" The emperor asked the crown prince, \"Is this so?", idiomatic: "\" The Liang emperor asked the crown prince, \"Is this so?" },
  { zh: "」對曰：「然。", literal: "\" He answered, \"It is so.", idiomatic: "\" He answered, \"It is so." },
  { zh: "」上將誅之。", literal: "\" The emperor was about to execute them.", idiomatic: "\" The Liang emperor was about to execute them." },
  { zh: "太子曰：「賊以異等為名耳；", literal: "The prince said, \"The rebels use Yi and the others only as a name;", idiomatic: "The prince said, \"The rebels use Yi and the others only as a name;" },
  { zh: "今日殺之，無救於急，適足貽笑將來，俟賊平，誅之未晚。", literal: "to kill them today will not help the crisis, but will only invite laughter hereafter; wait until the rebels are crushed, and execution will not be too late.", idiomatic: "to kill them today will not help the crisis, but will only invite laughter hereafter; wait until the rebels are crushed, and execution will not be too late." },
  { zh: "」上乃止。", literal: "\" The emperor then stopped.", idiomatic: "\" The Liang emperor then stopped." },
  { zh: "景繞城既匝，百道俱攻，鳴鼓吹脣，喧聲震地，縱火燒大司馬、東、西華諸門。", literal: "Jing having encircled the city, attacked from a hundred routes, drums and horns sounded, noise shook the earth, and fire was set to the Grand Marshal and Eastern and Western Splendor gates.", idiomatic: "Hou Jing having encircled the city, attacked from a hundred routes, drums and horns sounded, noise shook the earth, and fire was set to the Grand Marshal and Eastern and Western Splendor gates." },
  { zh: "羊侃使鑿門上為竅，下水沃火；", literal: "Yang Kan had holes cut in the gates above and water poured down to quench the fire;", idiomatic: "Yang Kan had holes cut in the gates above and water poured down to quench the fire;" },
  { zh: "太子自捧銀鞍，往賞戰士；", literal: "the prince himself carried a silver saddle to reward the warriors;", idiomatic: "the prince himself carried a silver saddle to reward the warriors;" },
  { zh: "直閣將軍朱思帥戰士數人逾城出外灑水，久之方滅。", literal: "Direct Attendant General Zhu Si led several warriors over the wall outside to pour water; only after long effort was it extinguished.", idiomatic: "Direct Attendant General Zhu Si led several warriors over the wall outside to pour water; only after long effort was it extinguished." },
  { zh: "賊又以長柯斧斫東掖門，門將開，羊侃鑿扇為孔，以槊刺殺二人，斫者乃退。", literal: "The rebels again used long-handled axes on the Eastern Side Gate; as the gate was about to open, Yang Kan bored holes in the leaves and speared two men to death, and the choppers withdrew.", idiomatic: "The rebels again used long-handled axes on the Eastern Side Gate; as the gate was about to open, Yang Kan bored holes in the leaves and speared two men to death, and the choppers withdrew." },
  { zh: "景據公車府，正德據左衛府，景黨宋子仙據東宮，范桃棒據同泰寺。", literal: "Jing held the Public Chariots Office, Zhengde the Left Guard Office, Jing's partisan Song Zixian the Eastern Palace, and Fan Taobang Tongtai Temple.", idiomatic: "Hou Jing held the Public Chariots Office, Zhengde the Left Guard Office, Song Zixian the Eastern Palace, and Fan Taobang Tongtai Temple." },
  { zh: "景取東宮妓數百，分給軍士。", literal: "Jing took several hundred Eastern Palace courtesans and distributed them to the soldiers.", idiomatic: "Hou Jing took several hundred Eastern Palace courtesans and distributed them to the soldiers." },
  { zh: "東宮近城，景眾登其牆射城內。", literal: "The Eastern Palace was near the wall; Jing's men climbed its ramparts and shot into the city.", idiomatic: "The Eastern Palace was near the wall; his men climbed its ramparts and shot into the city." },
  { zh: "至夜，景於東宮置酒奏樂，太子遣人焚之，台殿及所聚圖書皆盡。", literal: "At night Jing set wine and music in the Eastern Palace; the prince sent men to burn it—the terrace halls and collected books were all destroyed.", idiomatic: "At night Hou Jing set wine and music in the Eastern Palace; the prince sent men to burn it—the terrace halls and collected books were all destroyed." },
  { zh: "景又燒乘黃廄、士林館、太府寺。", literal: "Jing also burned the Imperial Horse Stable, the Forest of Scholars Hall, and the Grand Treasury.", idiomatic: "He also burned the Imperial Horse Stable, the Forest of Scholars Hall, and the Grand Treasury." },
  { zh: "癸丑，景作木驢數百攻城，城上投石碎之。", literal: "On guichou, Jing built several hundred wooden siege carts; stones cast from the wall shattered them.", idiomatic: "On guichou, Hou Jing built several hundred wooden siege carts; stones cast from the wall shattered them." },
  { zh: "景更作尖項木驢，石不能破。", literal: "Jing then made pointed wooden carts that stones could not break.", idiomatic: "He then made pointed wooden carts that stones could not break." },
  { zh: "羊侃使作雉尾炬，灌以膏蠟，叢擲焚之，俄盡。", literal: "Yang Kan had pheasant-tail torches made, soaked in grease and wax, and hurled in bundles to burn them—all were soon consumed.", idiomatic: "Yang Kan had pheasant-tail torches made, soaked in grease and wax, and hurled in bundles to burn them—all were soon consumed." },
  { zh: "景又作登城樓，高十餘丈，欲臨射城中。", literal: "Jing also built siege towers more than ten zhang high, intending to overlook and shoot into the city.", idiomatic: "He also built siege towers more than ten zhang high, intending to overlook and shoot into the city." },
  { zh: "侃曰：「車高塹虛，彼來必倒，可臥而觀之。", literal: "Kan said, \"The cart is high and the moat hollow—when they come they are sure to topple; we may lie down and watch.", idiomatic: "Yang Kan said, \"The cart is high and the moat hollow—when they come they are sure to topple; we may lie down and watch." },
  { zh: "」及車動，果倒。", literal: "\" When the cart moved, it indeed fell.", idiomatic: "\" When the cart moved, it indeed fell." },
  { zh: "景攻既不克，士卒死傷多，乃築長圍以絕內外，又啟求誅朱異等。", literal: "Jing's assault having failed and his troops suffering many dead and wounded, he built a long encirclement to cut inner from outer and again memorialized asking for the execution of Zhu Yi and the others.", idiomatic: "Hou Jing's assault having failed and his troops suffering many dead and wounded, he built a long encirclement to cut inner from outer and again memorialized asking for the execution of Zhu Yi and the others." },
  { zh: "城中亦射賞格出外曰：「有能送景首者，授以景位，並錢一億萬，布絹各萬匹。", literal: "The city also shot a reward notice outward, saying, \"Whoever can deliver Jing's head shall receive Jing's rank, plus a hundred million cash, ten thousand bolts each of cloth and silk.", idiomatic: "The city also shot a reward notice outward, saying, \"Whoever can deliver Hou Jing's head shall receive his rank, plus a hundred million cash, ten thousand bolts each of cloth and silk." },
  { zh: "」朱異、張綰議出兵擊之，上問羊侃，侃曰：「不可。", literal: "\" Zhu Yi and Zhang Chuo debated sallying out to attack; the emperor asked Yang Kan, and Kan said, \"It cannot be done.", idiomatic: "\" Zhu Yi and Zhang Chuo debated sallying out to attack; the Liang emperor asked Yang Kan, and he said, \"It cannot be done." },
  { zh: "今出人若少，不足破賊，徒挫銳氣；", literal: "If we send out too few now, we cannot break the rebels and will only blunt our keen spirit;", idiomatic: "If we send out too few now, we cannot break the rebels and will only blunt our keen spirit;" },
  { zh: "若多，則一旦失利，門隘橋小，必大致失亡。", literal: "if we send many and lose in one stroke, the gates are narrow and the bridges small—we will suffer great losses.", idiomatic: "if we send many and lose in one stroke, the gates are narrow and the bridges small—we will suffer great losses." },
  { zh: "」異等不從，使千餘人出戰。", literal: "\" Yi and the others would not listen and sent out more than a thousand men to fight.", idiomatic: "\" Zhu Yi and the others would not listen and sent out more than a thousand men to fight." },
  { zh: "鋒未及交，退走，爭橋赴水死者大半。", literal: "Before the vanguards met, they retreated and fled; scrambling for the bridge and rushing into the water, more than half died.", idiomatic: "Before the vanguards met, they retreated and fled; scrambling for the bridge and rushing into the water, more than half died." },
  { zh: "侃子鷟，為景所獲，執至城下，以示侃，侃曰：「我傾宗報主，猶恨不足，豈計一子，幸早殺之！", literal: "Kan's son Zhuo was captured by Jing and brought beneath the wall to show Kan; Kan said, \"I would spend my whole clan for my lord and still regret it is not enough—how would I count one son? I beg you kill him quickly!", idiomatic: "Yang Kan's son Zhuo was captured by Hou Jing and brought beneath the wall to show him; Yang Kan said, \"I would spend my whole clan for my lord and still regret it is not enough—how would I count one son? I beg you kill him quickly!" },
  { zh: "」數日，復持來，侃謂鷟曰：「久以汝為死矣，猶在邪！", literal: "\" After several days they brought him again; Kan said to Zhuo, \"I had long thought you dead—still alive!", idiomatic: "\" After several days they brought him again; Yang Kan said to Zhuo, \"I had long thought you dead—still alive!" },
  { zh: "」引弓射之。", literal: "\" He drew his bow and shot at him.", idiomatic: "\" He drew his bow and shot at him." },
  { zh: "景以其忠義，亦不之殺。", literal: "Jing, because of his loyalty and righteousness, did not kill him either.", idiomatic: "Hou Jing, because of his loyalty and righteousness, did not kill him either." },
  { zh: "莊鐵慮景不克，托稱迎母，與左右數十人趣歷陽。", literal: "Zhuang Tie, fearing Jing would not prevail, claimed he was going to fetch his mother and hurried to Liyang with several dozen followers.", idiomatic: "Zhuang Tie, fearing Hou Jing would not prevail, claimed he was going to fetch his mother and hurried to Liyang with several dozen followers." },
  { zh: "先遣書紿田英、郭駱曰：「侯王已為台軍所殺，國家使我歸鎮。", literal: "He first sent a letter deceiving Tian Ying and Guo Luo, saying, \"The Prince of Hou has been killed by imperial troops; the state sends me back to my post.", idiomatic: "He first sent a letter deceiving Tian Ying and Guo Luo, saying, \"The Prince of Hou has been killed by imperial troops; the state sends me back to my post." },
  { zh: "」駱等大懼，棄城奔壽陽，鐵入城，不敢守，奉其母奔尋陽。", literal: "\" Luo and the others were greatly afraid, abandoned the city, and fled to Shouyang; Tie entered the city, dared not hold it, and took his mother to Xunyang.", idiomatic: "\" Luo and the others were greatly afraid, abandoned the city, and fled to Shouyang; Tie entered the city, dared not hold it, and took his mother to Xunyang." },
  { zh: "十一月，戊午朔，刑白馬，祀蚩尤於太極殿前。", literal: "In the eleventh month, on the first day wuwu, a white horse was sacrificed and Chiyou worshipped before the Hall of Supreme Ultimate.", idiomatic: "In the eleventh month, on the first day wuwu, a white horse was sacrificed and Chiyou worshipped before the Hall of Supreme Ultimate." },
  { zh: "臨賀王正德即帝位於儀賢堂，下詔稱：「普通已來，奸邪亂政，上久不豫，社稷將危。", literal: "Prince Zhengde of Linhe took the throne in the Hall of Worthy Rites and issued an edict, saying, \"Since the Putong era wicked men have disordered government; the emperor has long been unwell and the altars of state are in peril.", idiomatic: "Prince Zhengde of Linhe took the throne in the Hall of Worthy Rites and issued an edict, saying, \"Since the Putong era wicked men have disordered government; the emperor has long been unwell and the altars of state are in peril." },
  { zh: "河南王景，釋位來朝，猥用朕躬，紹茲寶位，可大赦，改元正平。", literal: "Prince Jing of Henan, relinquishing his post to come to court, has unworthily used Our person to continue this precious throne; a general amnesty is proclaimed and the era is changed to Zhengping.", idiomatic: "Prince Jing of Henan, relinquishing his post to come to court, has unworthily used Our person to continue this precious throne; a general amnesty is proclaimed and the era is changed to Zhengping." },
  { zh: "」立其世子見理為皇太子，以景為丞相，妻以女，並出家之寶貨悉助軍費。", literal: "\" He made his heir Jianli crown prince, made Jing chancellor, gave him his daughter in marriage, and contributed all the family's treasures to military expenses.", idiomatic: "\" He made his heir Jianli crown prince, made Hou Jing chancellor, gave him his daughter in marriage, and contributed all the family's treasures to military expenses." },
  { zh: "於是景營於闕前，分其兵二千人攻東府；", literal: "Thereupon Jing encamped before the palace gates and sent two thousand of his troops to attack the Eastern Palace;", idiomatic: "Thereupon Hou Jing encamped before the palace gates and sent two thousand of his troops to attack the Eastern Palace;" },
  { zh: "南浦侯推拒之，三日，不克。", literal: "Marquis Tui of Nanpu resisted; three days passed without success.", idiomatic: "Marquis Tui of Nanpu resisted; three days passed without success." },
  { zh: "景自往攻之，矢石雨下，宣城王防閤許伯眾潛引景眾登城。", literal: "Jing went to attack in person; arrows and stones fell like rain; Xu Bojhong, gate guard of Prince Xuancheng, secretly led Jing's men onto the wall.", idiomatic: "Hou Jing went to attack in person; arrows and stones fell like rain; Xu Bojhong, gate guard of Prince Xuancheng, secretly led his men onto the wall." },
  { zh: "辛酉，克之；", literal: "On xinyou, it was taken;", idiomatic: "On xinyou, it was taken;" },
  { zh: "殺南浦侯推及城中戰士三千人，載其屍聚於杜姥宅，遙語城中人曰：「若不早降，正當如此！", literal: "Marquis Tui of Nanpu and three thousand warriors in the city were killed; their corpses were loaded and piled at Old Du's house, and they shouted to the city, \"If you do not surrender soon, this is exactly what awaits!", idiomatic: "Marquis Tui of Nanpu and three thousand warriors in the city were killed; their corpses were piled at Old Du's house, and they shouted to the city, \"If you do not surrender soon, this is exactly what awaits!" },
  { zh: "景聲言上已晏駕，雖城中亦以為然。", literal: "Jing spread word that the emperor had already died; even within the city many believed it.", idiomatic: "Hou Jing spread word that the Liang emperor had already died; even within the city many believed it." },
  { zh: "壬戌，太子請上巡城，上幸大司馬門，城上聞蹕聲，皆鼓噪流涕，眾心粗安。", literal: "On renxu, the prince asked the emperor to inspect the walls; the emperor went to the Grand Marshal Gate; hearing the imperial procession on the wall, all cheered and wept, and public feeling was somewhat calmed.", idiomatic: "On renxu, the prince asked the Liang emperor to inspect the walls; he went to the Grand Marshal Gate; hearing the imperial procession on the wall, all cheered and wept, and public feeling was somewhat calmed." },
  { zh: "江子一之敗還也，上責之。", literal: "When Jiang Ziyi returned defeated, the emperor rebuked him.", idiomatic: "When Jiang Ziyi returned defeated, the Liang emperor rebuked him." },
  { zh: "子一拜謝曰：「臣以身許國，常恐不得其死；", literal: "Ziyi bowed and said, \"Your servant pledged his body to the state and always feared he would not find death;", idiomatic: "Ziyi bowed and said, \"Your servant pledged his body to the state and always feared he would not find death;" },
  { zh: "今所部皆棄臣去，臣以一夫安能擊賊！", literal: "now my command has all abandoned me—how can one man strike the rebels!", idiomatic: "now my command has all abandoned me—how can one man strike the rebels!" },
  { zh: "若賊遂能至此，臣誓當碎身以贖前罪，不死闕前，當死闕後。", literal: "If the rebels can reach this far, your servant vows to shatter his body to atone for past fault—if not dead before the gate, then dead behind it.", idiomatic: "If the rebels can reach this far, your servant vows to shatter his body to atone for past fault—if not dead before the gate, then dead behind it." },
  { zh: "」乙亥，子一啟太子，與弟尚書左丞子四、東宮主帥子五帥所領百餘人開承明門出戰。", literal: "\" On yihai, Ziyi reported to the prince and, with his brothers Left Assistant Minister Zisi and Eastern Palace commander Ziwu, led more than a hundred men under their command out through Chenming Gate to fight.", idiomatic: "\" On yihai, Ziyi reported to the prince and, with his brothers Left Assistant Minister Zisi and Eastern Palace commander Ziwu, led more than a hundred men under their command out through Chenming Gate to fight." },
  { zh: "子一直抵賊營，賊伏兵不動。", literal: "Ziyi went straight to the rebel camp; the ambush did not stir.", idiomatic: "Ziyi went straight to the rebel camp; the ambush did not stir." },
  { zh: "子一呼曰：「賊輩何不速出！", literal: "Ziyi shouted, \"Rebels, why not come out quickly!", idiomatic: "Ziyi shouted, \"Rebels, why not come out quickly!" },
  { zh: "」久之，賊騎出，夾攻之。", literal: "\" After long delay rebel cavalry came out and attacked from both sides.", idiomatic: "\" After long delay rebel cavalry came out and attacked from both sides." },
  { zh: "子一徑前，引槊刺賊；", literal: "Ziyi went straight forward and thrust his spear at the rebels;", idiomatic: "Ziyi went straight forward and thrust his spear at the rebels;" },
  { zh: "從者莫敢繼，賊解其肩而死。", literal: "none of his followers dared follow; the rebels cut off his shoulder and he died.", idiomatic: "none of his followers dared follow; the rebels cut off his shoulder and he died." },
  { zh: "子四、子五相謂曰：「與兄俱出，何面獨旋！", literal: "Zisi and Ziwu said to each other, \"We came out with our brother—what face have we to return alone!", idiomatic: "Zisi and Ziwu said to each other, \"We came out with our brother—what face have we to return alone!" },
  { zh: "」皆免冑赴賊。", literal: "\" Both removed their helmets and rushed at the rebels.", idiomatic: "\" Both removed their helmets and rushed at the rebels." },
  { zh: "子四中槊，洞胸而死；", literal: "Zisi was speared, pierced through the chest, and died;", idiomatic: "Zisi was speared, pierced through the chest, and died;" },
  { zh: "子五傷脰，還至塹，一慟而絕。", literal: "Ziwu was wounded in the neck; returning to the moat, he gave one sob and expired.", idiomatic: "Ziwu was wounded in the neck; returning to the moat, he gave one sob and expired." },
  { zh: "景初至建康，謂朝夕可拔，號令嚴整，士卒不敢侵暴。", literal: "When Jing first reached Jiankang, he thought the city could be taken within days; his orders were strict and soldiers dared not loot.", idiomatic: "When Hou Jing first reached Jiankang, he thought the city could be taken within days; his orders were strict and soldiers dared not loot." },
  { zh: "及屢攻不克，人心離沮。", literal: "After repeated assaults failed, hearts turned away and spirits sank.", idiomatic: "After repeated assaults failed, hearts turned away and spirits sank." },
  { zh: "景恐援兵四集，一旦潰去；", literal: "Jing feared relief troops would gather from four sides and he would collapse in a day;", idiomatic: "Hou Jing feared relief troops would gather from four sides and he would collapse in a day;" },
  { zh: "又食石頭常平諸倉既盡，軍中乏食；", literal: "also the Shitou and Changping granaries were exhausted and the army lacked food;", idiomatic: "also the Shitou and Changping granaries were exhausted and the army lacked food;" },
  { zh: "乃縱士卒掠奪民米及金帛子女。", literal: "he then let soldiers plunder the people's grain, gold, silk, and daughters.", idiomatic: "he then let soldiers plunder the people's grain, gold, silk, and daughters." },
  { zh: "是後米一升直七八萬錢，人相食，餓死者什五六。", literal: "After this one sheng of rice cost seven or eight hundred thousand cash; men ate one another; five or six in ten died of hunger.", idiomatic: "After this one sheng of rice cost seven or eight hundred thousand cash; men ate one another; five or six in ten died of hunger." },
  { zh: "乙丑，景於城東、西起土山，驅迫士民，不限貴賤，亂加毆捶，疲羸者因殺以填山，號哭動地。", literal: "On yichou, Jing raised earthen hills east and west of the city, driving commoners and gentry without distinction of rank, beating them at random; the weak and wasted were killed to fill the hills—wailing shook the earth.", idiomatic: "On yichou, Hou Jing raised earthen hills east and west of the city, driving commoners and gentry without distinction of rank, beating them at random; the weak and wasted were killed to fill the hills—wailing shook the earth." },
  { zh: "民不敢竄匿，並出從之，旬日間，眾至數萬。", literal: "The people dared not hide and all came out to follow; within ten days the crowd reached tens of thousands.", idiomatic: "The people dared not hide and all came out to follow; within ten days the crowd reached tens of thousands." },
  { zh: "城中亦築土山以應之。", literal: "Within the city they also built earthen hills in response.", idiomatic: "Within the city they also built earthen hills in response." },
  { zh: "太子、宣城王已下，皆親負土，執畚鍤，於山上起芙蓉層樓，高四丈，飾以錦罽，募敢死士二千人，厚衣袍鎧，謂之「僧騰客」，分配二山，晝夜交戰不息。", literal: "From the prince and Prince Xuancheng downward, all personally carried earth and wielded spades; on the hills they raised lotus-layered towers four zhang high, adorned with brocade; two thousand dare-to-die men were recruited, heavily clad in robes and armor, called \"Monk Soarers\"; they were assigned to both hills and fought day and night without cease.", idiomatic: "From the prince and Prince Xuancheng downward, all personally carried earth and wielded spades; on the hills they raised lotus-layered towers four zhang high, adorned with brocade; two thousand dare-to-die men were recruited, heavily clad in robes and armor, called \"Monk Soarers\"; they were assigned to both hills and fought day and night without cease." },
  { zh: "會大雨，城內土山崩；", literal: "Heavy rain came; the inner earthen hill collapsed;", idiomatic: "Heavy rain came; the inner earthen hill collapsed;" },
  { zh: "賊乘之，垂入，苦戰不能禁。", literal: "the rebels seized the moment and nearly entered; bitter fighting could not stop them.", idiomatic: "the rebels seized the moment and nearly entered; bitter fighting could not stop them." },
  { zh: "羊侃令多擲火，為火城以斷其路，徐於內築城，賊不能進。", literal: "Yang Kan ordered much fire cast down, made a fire wall to cut their path, and slowly built a wall within; the rebels could not advance.", idiomatic: "Yang Kan ordered much fire cast down, made a fire wall to cut their path, and slowly built a wall within; the rebels could not advance." },
  { zh: "景募人奴降者，悉免為良；", literal: "Jing recruited household slaves who surrendered and freed them all as commoners;", idiomatic: "Hou Jing recruited household slaves who surrendered and freed them all as commoners;" },
  { zh: "得朱異奴，以為儀同三司，異家資產悉與之。", literal: "obtaining Zhu Yi's slave, he made him Equal in Honor to the Three Dukes and gave him all of Yi's family property.", idiomatic: "obtaining Zhu Yi's slave, he made him Equal in Honor to the Three Dukes and gave him all of Yi's family property." },
  { zh: "奴乘良馬，衣錦袍，於城下仰詬異曰：「汝五十年仕宦，方得中領軍；", literal: "The slave rode a fine horse and wore a brocade robe; beneath the wall he looked up and cursed Yi, saying, \"You served fifty years in office and only then became Central Army Commander;", idiomatic: "The slave rode a fine horse and wore a brocade robe; beneath the wall he looked up and cursed Zhu Yi, saying, \"You served fifty years in office and only then became Central Army Commander;" },
  { zh: "我始事侯王，已為儀同矣！", literal: "I have only just begun serving the Prince of Hou and am already Equal in Honor!", idiomatic: "I have only just begun serving the Prince of Hou and am already Equal in Honor!" },
  { zh: "」於是三日之中，群奴出就景者以千數，景皆厚撫以配軍，人人感恩，為之致死。", literal: "\" Within three days slaves who went over to Jing numbered in the thousands; Jing treated them all generously and assigned them to the army; each man was grateful and fought to the death for him.", idiomatic: "\" Within three days slaves who went over to Hou Jing numbered in the thousands; he treated them all generously and assigned them to the army; each man was grateful and fought to the death for him." },
  { zh: "荊州刺史湘東王繹聞景圍台城，丙寅，戒嚴，移檄所督湘州刺史河東王譽、雍州刺史岳陽王察、江州刺史當陽公大心、郢州刺史南平王恪等，發兵入援。", literal: "Jingzhou Inspector Prince Yi of Xiangdong, hearing Jing had besieged the capital enclosure, on bingyin ordered martial law and sent proclamations to those under his command—Jingzhou Inspector Prince Yu of Hedong, Yongzhou Inspector Prince Cha of Yueyang, Jiangzhou Inspector Duke Daxin of Dangyang, Yingzhou Inspector Prince Ke of Nanping, and others—to raise troops and march to the rescue.", idiomatic: "Jingzhou Inspector Prince Yi of Xiangdong, hearing Hou Jing had besieged the capital enclosure, on bingyin ordered martial law and sent proclamations to those under his command—Jingzhou Inspector Prince Yu of Hedong, Yongzhou Inspector Prince Cha of Yueyang, Jiangzhou Inspector Duke Daxin of Dangyang, Yingzhou Inspector Prince Ke of Nanping, and others—to raise troops and march to the rescue." },
  { zh: "大心，大器之弟；", literal: "Daxin was the younger brother of Daqi.", idiomatic: "Daxin was the younger brother of Daqi." },
  { zh: "恪，偉之子也。", literal: "Ke was Wei's son.", idiomatic: "Ke was Wei's son." },
  { zh: "朱異遺景書，為陳禍福。", literal: "Zhu Yi sent Jing a letter explaining fortune and disaster.", idiomatic: "Zhu Yi sent Hou Jing a letter explaining fortune and disaster." },
  { zh: "景報書，並告城中士民，以為：「梁自近歲以來，權幸用事，割剝齊民，以供嗜欲。", literal: "Jing replied and also addressed the gentry and people in the city, saying, \"In recent years Liang has been ruled by favorites who strip the common people to feed their appetites.", idiomatic: "Hou Jing replied and also addressed the gentry and people in the city, saying, \"In recent years Liang has been ruled by favorites who strip the common people to feed their appetites." },
  { zh: "如曰不然，公等試觀：今日國家池苑，王公第宅，僧尼寺塔；", literal: "If you say this is not so, gentlemen, look: today's state pools and parks, princes' mansions, monks' and nuns' temples and pagodas;", idiomatic: "If you say this is not so, gentlemen, look: today's state pools and parks, princes' mansions, monks' and nuns' temples and pagodas;" },
  { zh: "及在位庶僚，姬姜百室，僕從數千，不耕不織，錦衣玉食；", literal: "and officials in office, concubines filling a hundred chambers, retainers numbering thousands—neither plowing nor weaving, yet brocade robes and jade fare;", idiomatic: "and officials in office, concubines filling a hundred chambers, retainers numbering thousands—neither plowing nor weaving, yet brocade robes and jade fare;" },
  { zh: "不奪百姓，從何得之！", literal: "if they do not seize from the common people, whence do they obtain it!", idiomatic: "if they do not seize from the common people, whence do they obtain it!" },
  { zh: "僕所以趨赴闕庭，指誅權佞，非傾社稷。", literal: "Your servant hurries to the court gate to execute the power-holders—not to overturn the altars of state.", idiomatic: "Your servant hurries to the court gate to execute the power-holders—not to overturn the altars of state." },
  { zh: "今城中指望四方入援，吾觀王侯、諸將，志在全身，誰能竭力致死，與吾爭勝負哉！", literal: "Now within the city you look to relief from four directions; I see princes and generals whose aim is to save themselves—who will exhaust his strength and die fighting to contend victory and defeat with me!", idiomatic: "Now within the city you look to relief from four directions; I see princes and generals whose aim is to save themselves—who will exhaust his strength and die fighting to contend victory and defeat with me!" },
  { zh: "長江天險，二曹所歎，吾一葦航之，日明氣淨。", literal: "The Yangtze is heaven's barrier, what the two Caos lamented—I crossed it on a single reed, under bright sun and clear air.", idiomatic: "The Yangtze's natural fortifications made Cao Cao and Cao Pi sigh—I crossed it on a reed boat, under bright sun and clear air." },
  { zh: "自非天人允協，何能如是！", literal: "Unless heaven and men were in accord, how could it be so!", idiomatic: "Unless heaven and men were in accord, how could such a thing happen!" },
  { zh: "幸各三思，自求元吉！", literal: "I hope each of you will think thrice and seek your own great fortune!", idiomatic: "Think carefully, each of you, and seek your own fortune!" },
  { zh: "景又奉啟於東魏主，稱：「臣進取壽春，暫欲停憩。", literal: "Jing also submitted a memorial to the Eastern Wei ruler, saying, \"Your servant advanced on Shouchun intending to halt and rest awhile.", idiomatic: "Hou Jing also submitted a memorial to the Eastern Wei emperor, saying, \"Your servant advanced on Shouchun intending to halt and rest awhile." },
  { zh: "而蕭衍識此運終，自辭寶位；", literal: "But Xiao Yan perceived this fate was ending and resigned the imperial seat himself;", idiomatic: "But Xiao Yan perceived his fate was ending and resigned the throne himself;" },
  { zh: "臣軍未入其國，已投同泰捨身。", literal: "before your servant's army entered his state, he had already gone to Tongtai Temple to relinquish his body.", idiomatic: "before your servant's army entered his realm, he had already gone to Tongtai Temple to renounce the throne." },
  { zh: "去月二十九日，屆此建康。", literal: "On the twenty-ninth of last month, I arrived at Jiankang.", idiomatic: "On the twenty-ninth of last month, I arrived at Jiankang." },
  { zh: "江海未蘇，干戈暫止，永言故鄉，人馬同戀。", literal: "Rivers and seas are not yet calmed, weapons have briefly ceased—ever thinking of home, men and horses alike long for it.", idiomatic: "Rivers and seas are not yet calmed, arms have briefly ceased—I long for home, as do my men and horses." },
  { zh: "尋當整轡，以奉聖顏。", literal: "Soon I shall rein in and return to pay homage to Your Majesty's face.", idiomatic: "Soon I shall turn home to pay homage to Your Majesty." },
  { zh: "臣之母、弟，久謂屠滅，近奉明敕，始承猶在。", literal: "Your servant's mother and younger brother, long thought slaughtered, by recent clear edict I first learn they still live.", idiomatic: "Your servant's mother and brother, long thought dead, I have just learned by edict that they still live." },
  { zh: "斯乃陛下寬仁，大將軍恩念，臣之弱劣，知何仰報！", literal: "This is Your Majesty's breadth and mercy, the Grand General's kindness—your servant is weak and lowly, how can I repay such favor!", idiomatic: "This is Your Majesty's mercy and the Grand General's kindness—your servant is weak and lowly; how can I repay it!" },
  { zh: "今輒繼啟迎臣母、弟、妻、兒，伏願聖慈，特賜裁放！", literal: "Now I humbly submit again asking to receive my mother, brother, wife, and children—I prostrate myself, hoping for Your Majesty's holy compassion to grant release!", idiomatic: "I humbly ask again that my mother, brother, wife, and children be released—I prostrate myself, hoping Your Majesty will grant it!" },
  { zh: "己巳，湘東王繹遣司馬吳曄、天門太守樊文皎等將兵發江陵。", literal: "On jisi, Prince of Xiangdong Yi dispatched Staff Officer Wu Ye, Tiantai prefect Fan Wenjiao, and others leading troops from Jiangling.", idiomatic: "On jisi, Prince Xiao Yi of Xiangdong dispatched staff officer Wu Ye, Tiantai prefect Fan Wenjiao, and others with troops from Jiangling." },
  { zh: "陳昕為景所擒，景與之極飲，使昕收集部曲，欲用之。", literal: "Chen Xin was captured by Jing; Jing drank heavily with him and had Xin gather his followers, intending to use him.", idiomatic: "Chen Xin was captured by Hou Jing; Jing drank heavily with him and had Xin gather his followers, intending to employ him." },
  { zh: "昕不可，景使其儀同三司范桃棒囚之。", literal: "Xin refused; Jing had his Equal in Honor to the Three Dukes Fan Taobang imprison him.", idiomatic: "Xin refused; Jing had Fan Taobang, Equal to the Three Dukes, imprison him." },
  { zh: "昕因說桃棒，使帥所部襲殺王偉、宋子仙，詣城降。", literal: "Xin then persuaded Taobang to lead his troops in a surprise attack to kill Wang Wei and Song Zixian and surrender to the city.", idiomatic: "Xin then persuaded Taobang to lead his troops in a surprise attack on Wang Wei and Song Zixian, then surrender to the city." },
  { zh: "桃棒從之，潛遣昕夜縋入城。", literal: "Taobang agreed and secretly sent Xin by rope into the city at night.", idiomatic: "Taobang agreed and secretly sent Xin over the wall into the city by night." },
  { zh: "上大喜，敕鐫銀券賜桃棒曰：「事定之日，封汝河南王，即有景眾，並給金帛女樂。", literal: "The emperor was greatly pleased and ordered a silver tally engraved and given to Taobang, saying, \"When affairs are settled, you shall be made Prince of Henan; Hou Jing's troops shall be yours, with gold, silk, and female musicians besides.", idiomatic: "The emperor was greatly pleased and ordered a silver tally for Taobang: \"When this is settled, you shall be Prince of Henan; Hou Jing's troops will be yours, along with gold, silk, and musicians." },
  { zh: "」太子恐其詐，猶豫不決，上怒曰：「受降常理，何忽致疑！", literal: "\" The Crown Prince feared deception and hesitated; the emperor angrily said, \"Accepting surrender is common sense—why suddenly doubt it!", idiomatic: "\" The crown prince feared a ruse and hesitated; the emperor angrily said, \"Accepting surrender is common sense—why doubt it now!" },
  { zh: "」太子召公卿會議，朱異、傅岐曰：「桃棒降必非謬。", literal: "\" The Crown Prince summoned ministers to confer; Zhu Yi and Fu Qi said, \"Taobang's surrender cannot be false.", idiomatic: "\" The crown prince summoned ministers to confer; Zhu Yi and Fu Qi said, \"Taobang's surrender cannot be false." },
  { zh: "桃棒既降，賊景必驚，乘此擊之，可大破也。", literal: "Once Taobang has surrendered, the rebel Jing will surely be alarmed; strike now and he can be greatly defeated.", idiomatic: "Once Taobang surrenders, Hou Jing will be alarmed; strike now and we can break him utterly." },
  { zh: "」太子曰：「吾堅城自守以俟外援，援兵既至，賊豈足平！", literal: "\" The Crown Prince said, \"I will hold the walls and wait for outside aid; when relief arrives, will the rebels not be easily crushed!", idiomatic: "\" The crown prince said, \"I will hold the walls and wait for relief; when reinforcements arrive, will the rebels not be easily crushed!" },
  { zh: "此萬全策也。", literal: "This is the completely safe plan.", idiomatic: "That is the safest course." },
  { zh: "今開門納桃棒，桃棒之情，何易可知！", literal: "To open the gates now and admit Taobang—how easily can his intentions be known!", idiomatic: "To open the gates and admit Taobang now—how can we know his true intent!" },
  { zh: "萬一為變，悔無所及。", literal: "If by chance there is treachery, regret will come too late.", idiomatic: "If he turns on us, it will be too late for regret." },
  { zh: "社稷事重，須更詳之。", literal: "The fate of the state is grave—it must be considered further.", idiomatic: "The fate of the state hangs on this—it must be weighed more carefully." },
  { zh: "」異曰：「殿下若以社稷之急，宜納桃棒；", literal: "\" Yi said, \"If Your Highness considers the state's emergency, Taobang should be admitted;", idiomatic: "\" Zhu Yi said, \"If Your Highness weighs the state's emergency, Taobang should be admitted;" },
  { zh: "如其猶豫，非異所知。", literal: "if you hesitate, that is beyond what Yi can know.", idiomatic: "if you hesitate, I cannot advise further." },
  { zh: "」太子終不能決。", literal: "\" The Crown Prince could not decide in the end.", idiomatic: "\" The crown prince could not decide." },
  { zh: "桃棒又使昕啟曰：「今止將所領五百人，若至城門，皆自脫甲，乞朝廷開門賜容。", literal: "Taobang again had Xin report: \"I will bring only five hundred men; at the gate they will all remove their armor—I beg the court to open and grant entry.", idiomatic: "Taobang sent Xin again: \"I will bring only five hundred men; at the gate they will remove their armor—I beg the court to open and admit us." },
  { zh: "事濟之後，保擒侯景。", literal: "Once the affair succeeds, I guarantee to capture Hou Jing.", idiomatic: "When it is done, I guarantee to capture Hou Jing." },
  { zh: "」太子見其懇切，愈疑之。", literal: "\" The Crown Prince saw how earnest it was and grew more suspicious.", idiomatic: "\" The crown prince saw how earnest it was and grew more suspicious." },
  { zh: "朱異拊膺曰：「失此，社稷事去矣！", literal: "Zhu Yi beat his breast and said, \"Miss this chance and the state is lost!", idiomatic: "Zhu Yi beat his breast: \"Miss this chance and the state is lost!" },
  { zh: "」俄而桃棒為部下所告，景拉殺之。", literal: "\" Shortly Taobang was reported by his subordinates; Jing had him torn apart and killed.", idiomatic: "\" Soon Taobang was betrayed by his own men; Jing had him torn apart and killed." },
  { zh: "陳昕不知，如期而出，景邀得之，逼使射書城中曰：「桃棒且輕將數十人先入。", literal: "Chen Xin did not know; he came out as agreed; Jing intercepted and seized him, forced him to shoot a letter into the city saying, \"Taobang will first enter lightly with several dozen men.", idiomatic: "Chen Xin, knowing nothing, came out as agreed; Jing intercepted him and forced him to shoot a letter into the city: \"Taobang will enter first with a small party." },
  { zh: "」景欲衷甲隨之，昕不肯，期以必死，乃殺之。", literal: "\" Jing wished to follow in hidden armor; Xin refused, vowing to die—so Jing killed him.", idiomatic: "\" Jing wished to follow in hidden armor; Xin refused, preferring death—so Jing killed him." },
  { zh: "景使蕭見理與儀同三司盧暉略戍東府。", literal: "Jing had Xiao Jianli and Equal in Honor to the Three Dukes Lu Huilue garrison the Eastern Palace.", idiomatic: "Jing posted Xiao Jianli and Lu Huilue, Equal to the Three Dukes, at the Eastern Palace." },
  { zh: "見理凶險，夜，與群盜剽劫於大桁，中流矢而死。", literal: "Jianli was fierce and dangerous; at night he robbed with bandits at the Great Bridge and was struck by an arrow and died midstream.", idiomatic: "Jianli was fierce and violent; by night he plundered with bandits at the Great Bridge and was struck by an arrow and killed." },
  { zh: "邵陵王綸行至鐘離，聞侯景已渡採石，綸晝夜兼道，旋軍入援，濟江，中流風起，人馬溺者什一二。", literal: "Prince of Shaoling Lun had reached Zhongli; hearing Hou Jing had crossed Caishi, Lun traveled day and night by double stages, turned his army to aid, crossed the river—midstream wind rose, one or two in ten of men and horses drowned.", idiomatic: "Prince Xiao Lun of Shaoling had reached Zhongli; hearing Hou Jing had crossed Caishi, he raced day and night to relieve the city, crossed the Yangtze—a sudden wind midstream drowned one or two men in ten." },
  { zh: "遂帥寧遠將軍西豐公大春、新淦公大成、永安侯確、安南侯駿、前譙州刺史趙伯超、武州刺史蕭弄璋等，步騎三萬，自京口西上。", literal: "He then led Ningyuan General Prince of Xifeng Dachun, Prince of Xingan Dacheng, Marquis of Yong'an Que, Marquis of Annan Jun, former Qiaozhou Inspector Zhao Bochao, Wuzhou Inspector Xiao Nongzhang, and others—thirty thousand foot and horse—from Jingkou westward.", idiomatic: "He then led Ningyuan general Prince Dachun of Xifeng, Prince Dacheng of Xingan, Marquis Que of Yong'an, Marquis Jun of Annan, former Qiaozhou inspector Zhao Bochao, Wuzhou inspector Xiao Nongzhang, and others—thirty thousand infantry and cavalry—from Jingkou westward." },
  { zh: "大成，大春之弟；", literal: "Dacheng was Dachun's younger brother;", idiomatic: "Dacheng was Dachun's younger brother;" },
  { zh: "確，綸之子；", literal: "Que was Lun's son;", idiomatic: "Que was Lun's son;" },
  { zh: "駿，懿之孫也。", literal: "Jun was Yi's grandson.", idiomatic: "Jun was the grandson of Xiao Yi." },
  { zh: "景遣軍至江乘拒綸軍。", literal: "Jing dispatched troops to Jiangcheng to block Lun's army.", idiomatic: "Jing dispatched troops to Jiangcheng to block Lun's army." },
  { zh: "趙伯超曰：「若從黃城大路，必與賊遇，不如徑指鐘山，突據廣莫門。", literal: "Zhao Bochao said, \"If we take the Huangcheng main road, we will surely meet the rebels; better to strike straight for Zhong Mountain and seize Guangmo Gate by surprise.", idiomatic: "Zhao Bochao said, \"If we take the Huangcheng main road, we will meet the rebels; better to strike straight for Zhong Mountain and seize Guangmo Gate by surprise." },
  { zh: "出賊不意，城圍必解矣。", literal: "Catching the rebels off guard, the siege will surely be lifted.", idiomatic: "Catching the rebels off guard, the siege will surely be lifted." },
  { zh: "」綸從之，夜行失道，迂二十餘里。", literal: "\" Lun agreed, marched by night, lost the way, and went twenty-odd li out of course.", idiomatic: "\" Lun agreed, marched by night, lost the way, and went twenty-odd li out of course." },
  { zh: "庚辰旦，營於蔣山。", literal: "At dawn on gengchen, he encamped on Mount Jiang.", idiomatic: "At dawn on gengchen, he encamped on Mount Jiang." },
  { zh: "景見之大駭，悉送所掠婦女、珍貨於石頭，具舟欲走。", literal: "Jing was greatly alarmed at the sight; he sent all plundered women and treasures to Shitou, prepared boats, and intended to flee.", idiomatic: "Jing was greatly alarmed; he sent all plundered women and treasures to Shitou, prepared boats, and intended to flee." },
  { zh: "分兵三道攻綸，綸與戰，破之。", literal: "He divided his army in three paths to attack Lun; Lun fought and defeated them.", idiomatic: "He divided his army in three columns to attack Lun; Lun fought and defeated them." },
  { zh: "時山巔寒雪，乃引軍下愛敬寺。", literal: "Cold snow lay on the mountain peaks; he then led his army down to Aijing Temple.", idiomatic: "Cold snow lay on the peaks; he led his army down to Aijing Temple." },
  { zh: "景陳兵於覆舟山北，乙酉，綸進軍玄武湖側，與景對陳，不戰。", literal: "Jing arrayed troops north of Fuzhou Mountain; on yiyou, Lun advanced to the side of Xuanwu Lake and faced Jing's array without fighting.", idiomatic: "Jing arrayed troops north of Fuzhou Mountain; on yiyou, Lun advanced to Xuanwu Lake and faced Jing's line without fighting." },
  { zh: "至暮，景更約明日會戰，綸許之。", literal: "At dusk, Jing proposed battle again the next day; Lun agreed.", idiomatic: "At dusk, Jing proposed battle again the next day; Lun agreed." },
  { zh: "安南侯駿見景軍退，以為走，即與壯士逐之；", literal: "Marquis of Annan Jun saw Jing's army retreat and thought they were fleeing; he immediately pursued with stalwart men;", idiomatic: "Marquis Jun of Annan saw Jing's army retreat and thought they were fleeing; he immediately pursued with picked men;" },
  { zh: "景旋軍擊之，駿敗走，趣綸軍。", literal: "Jing wheeled his army and struck; Jun was defeated and fled toward Lun's army.", idiomatic: "Jing wheeled his army and struck; Jun was defeated and fled toward Lun's army." },
  { zh: "趙伯超望見，亦引兵走，景乘勝追擊之，諸軍皆潰。", literal: "Zhao Bochao saw it from afar and also led his troops away; Jing pressed the victory in pursuit and all armies were routed.", idiomatic: "Zhao Bochao saw it from afar and also fled; Jing pressed the victory and all armies were routed." },
  { zh: "綸收餘兵近千人，入天保寺；", literal: "Lun gathered nearly a thousand remaining soldiers and entered Tianbao Temple;", idiomatic: "Lun gathered nearly a thousand survivors and entered Tianbao Temple;" },
  { zh: "景追之，縱火燒寺。", literal: "Jing pursued and set fire to the temple.", idiomatic: "Jing pursued and set fire to the temple." },
  { zh: "綸奔朱方，士卒踐冰雪，往往墮足。", literal: "Lun fled to Zhufang; soldiers treading ice and snow often lost their footing.", idiomatic: "Lun fled to Zhufang; soldiers treading ice and snow often lost their footing." },
  { zh: "景悉收綸輜重，生擒西豐公大春、安前司馬莊丘慧、主帥霍俊等而還。", literal: "Jing seized all of Lun's baggage, captured alive Prince of Xifeng Dachun, former Annan staff officer Zhuang Qiu Hui, commander Huo Jun, and others, and returned.", idiomatic: "Jing seized all of Lun's baggage, captured Prince Dachun of Xifeng, former Annan staff officer Zhuang Qiu Hui, commander Huo Jun, and others alive, and returned." },
  { zh: "丙戌，景陳所獲綸軍首虜鎧仗及大春等於城下，使言曰：「邵陵王已為亂兵所殺。", literal: "On bingxu, Jing displayed the heads, captives, armor, and weapons taken from Lun's army and Dachun and the rest below the walls, and had it said, \"Prince of Shaoling has been killed by mutinous soldiers.", idiomatic: "On bingxu, Jing displayed the heads, captives, armor, and weapons taken from Lun's army and Dachun and the rest below the walls, and had it said, \"Prince Shaoling has been killed by mutinous soldiers." },
  { zh: "」霍俊獨曰：「王小失利，已全軍還京口。", literal: "\" Huo Jun alone said, \"The prince suffered a small setback and has already returned with his whole army to Jingkou.", idiomatic: "\" Huo Jun alone said, \"The prince suffered a small setback and has already returned with his whole army to Jingkou." },
  { zh: "城中但堅守，援軍尋至。", literal: "Hold the city firm—relief will soon arrive.", idiomatic: "Hold the city firm—relief will soon arrive." },
  { zh: "」賊以刀毆其背，俊辭色彌厲；", literal: "\" The rebels beat his back with blades; Jun's words and bearing grew fiercer;", idiomatic: "\" The rebels beat his back with blades; Jun's words and bearing grew fiercer;" },
  { zh: "景義而釋之，臨賀王正德殺之。", literal: "Jing admired his loyalty and released him; Prince of Linhe Zhengde killed him.", idiomatic: "Jing admired his loyalty and released him; Prince Zhengde of Linhe killed him." },
  { zh: "是日晚，鄱陽王范遣其世子嗣與西豫州刺史裴之高、建安太守趙鳳舉各將兵入援，軍於蔡洲，以待上流諸軍，范以之高督江右援軍事。", literal: "That same evening, Prince of Poyang Fan sent his heir Si, Western Yuzhou Inspector Pei Zhigao, and Jian'an prefect Zhao Fengju each leading troops to aid, encamping at Caizhou to await upstream armies; Fan made Zhigao commander of relief forces on the river's right.", idiomatic: "That same evening, Prince Xiao Fan of Poyang sent his heir Si, Western Yuzhou inspector Pei Zhigao, and Jian'an prefect Zhao Fengju each with relief troops, encamping at Caizhou to await upstream armies; Fan made Zhigao commander of relief forces west of the river." },
  { zh: "景悉驅南岸居民於水北，焚其廬舍，大街已西，掃地俱盡。", literal: "Jing drove all residents of the south bank to the north of the water, burned their dwellings, and west of the main street swept the ground clean of everything.", idiomatic: "Jing drove all residents of the south bank to the north side, burned their dwellings, and west of the main street swept everything bare." },
  { zh: "北徐州刺史封山侯正表鎮鐘離，上召之入援，正表托以船糧未集，不進。", literal: "Northern Xuzhou Inspector Marquis of Fengshan Zhengbiao held Zhongli; the emperor summoned him to aid, but Zhengbiao pleaded that boats and grain were not yet assembled and did not advance.", idiomatic: "Northern Xuzhou inspector Marquis Zhengbiao of Fengshan held Zhongli; the emperor summoned him to aid, but Zhengbiao pleaded that boats and grain were not ready and did not advance." },
  { zh: "景以正表為南兗州刺史，封南郡王。", literal: "Jing made Zhengbiao Southern Yanzhou Inspector and enfeoffed him as Prince of Nanjun.", idiomatic: "Jing made Zhengbiao Southern Yanzhou inspector and enfeoffed him as Prince of Nanjun." },
  { zh: "正表乃於歐陽立柵以斷援軍，帥眾一萬，聲言入援，實欲襲廣陵。", literal: "Zhengbiao then built a stockade at Ouyang to cut off relief armies, leading ten thousand men under the claim of coming to aid but actually intending to strike Guangling.", idiomatic: "Zhengbiao then built a stockade at Ouyang to cut off relief armies, leading ten thousand men under the claim of coming to aid but actually intending to strike Guangling." },
  { zh: "密書誘廣陵令劉詢，使燒城為應，詢以告南兗州刺史南康王會理。", literal: "He sent secret letters to entice Guangling magistrate Liu Xun to burn the city as signal; Xun reported this to Southern Yanzhou Inspector Prince of Nankang Huili.", idiomatic: "He sent secret letters to entice Guangling magistrate Liu Xun to burn the city as signal; Xun reported this to Southern Yanzhou inspector Prince Huili of Nankang." },
  { zh: "十二月，會理使詢帥步騎千人夜襲正表，大破之；", literal: "In the twelfth month, Huili had Xun lead a thousand foot and horse in a night attack on Zhengbiao and routed him;", idiomatic: "In the twelfth month, Huili had Xun lead a thousand infantry and cavalry in a night attack on Zhengbiao and routed him;" },
  { zh: "正表走還鐘離。", literal: "Zhengbiao fled back to Zhongli.", idiomatic: "Zhengbiao fled back to Zhongli." },
  { zh: "詢收其兵糧，歸就會理，與之入援。", literal: "Xun seized his arms and grain, returned to join Huili, and entered to aid with him.", idiomatic: "Xun seized his arms and grain, rejoined Huili, and marched to relieve the city with him." },
  { zh: "癸巳，侍中、都官尚書羊侃卒，城中益懼。", literal: "On guisi, Attendant-in-Ordinary and Minister of Justice Yang Kan died; fear in the city increased.", idiomatic: "On guisi, attendant-in-ordinary and minister of justice Yang Kan died; fear in the city deepened." },
  { zh: "侯景大造攻具，陳於闕前，大車高數丈，一車二十輪。", literal: "Hou Jing greatly built siege engines and arrayed them before the palace gate—great carts several zhang high, twenty wheels to a cart.", idiomatic: "Hou Jing built great siege engines and arrayed them before the palace gate—carts several zhang high, twenty wheels each." },
  { zh: "丁酉，復進攻城，以蝦蟆車運土填塹。", literal: "On dingyou, he again advanced to attack the city, using toad carts to haul earth and fill the moat.", idiomatic: "On dingyou, he again attacked the city, using toad carts to haul earth and fill the moat." },
  { zh: "湘東王繹遣世子方等將步騎一萬入援建康，庚子，發公安。", literal: "Prince of Xiangdong Yi sent his heir Fangdeng leading ten thousand foot and horse to aid Jiankang; on gengzi they set out from Gong'an.", idiomatic: "Prince Xiao Yi of Xiangdong sent his heir Fangdeng with ten thousand infantry and cavalry to aid Jiankang; on gengzi they set out from Gong'an." },
  { zh: "繹又遣竟陵太守王僧辯將舟師萬人，出自漢川，載糧東下。", literal: "Yi also sent Jingling prefect Wang Senbian leading ten thousand river troops from Hanchuan, carrying grain eastward.", idiomatic: "Yi also sent Jingling prefect Wang Senbian with ten thousand river troops from Hanchuan, carrying grain eastward." },
  { zh: "方等有俊才，善騎射，每戰，親犯矢石，以死節自任。", literal: "Fangdeng had outstanding talent, skilled in riding and archery; in every battle he personally braved arrows and stones, taking death for honor as his charge.", idiomatic: "Fangdeng was gifted and skilled in riding and archery; in every battle he personally braved arrows and stones, holding death for honor as his charge." },
  { zh: "壬寅，侯景以火車焚台城東南樓。", literal: "On renyin, Hou Jing used fire carts to burn the southeast tower of the palace city.", idiomatic: "On renyin, Hou Jing used fire carts to burn the southeast tower of the palace city." },
  { zh: "材官吳景有巧思，於城內構地為樓，火才滅，新樓即立，賊以為神。", literal: "Artificer Wu Jing had clever ingenuity; within the city he built towers from the ground—as soon as fire died, new towers stood; the rebels thought it divine.", idiomatic: "Artificer Wu Jing was ingenious; within the city he built towers from the ground—as soon as fire died, new towers stood; the rebels thought it divine." },
  { zh: "景因火起，潛遣人於其下穿城。", literal: "Jing took advantage of the fire to secretly send men to tunnel under the wall.", idiomatic: "Jing took advantage of the fire to secretly send men to tunnel under the wall." },
  { zh: "城將崩，乃覺之；", literal: "The wall was about to collapse before they noticed;", idiomatic: "The wall was about to collapse before they noticed;" },
  { zh: "吳景於城內更築迂城，狀如卻月以擬之，兼擲火，焚其攻具，賊乃退走。", literal: "Wu Jing within the city built a curved inner wall shaped like a crescent moon to counter it, and also threw fire, burning their siege engines; the rebels then retreated.", idiomatic: "Wu Jing built a curved inner wall shaped like a crescent moon to counter it, and threw fire, burning their siege engines; the rebels retreated." },
  { zh: "太子遣洗馬元孟恭將千人自大司馬門出蕩，孟恭與左右奔降於景。", literal: "The Crown Prince sent Groom of the Heir Yuan Menggong leading a thousand men out from the Grand Marshal Gate to clear the area; Menggong and his attendants fled and surrendered to Jing.", idiomatic: "The crown prince sent groom of the heir Yuan Menggong with a thousand men out from the Grand Marshal Gate to clear the area; Menggong and his attendants fled and surrendered to Jing." },
  { zh: "己酉，景土山稍逼城樓，柳津命作地道以取其土，外山崩，壓賊且盡。", literal: "On jiyou, Jing's earthen mounds gradually pressed close to the tower; Liu Jin ordered tunnels dug to take their earth; the outer mound collapsed and crushed nearly all the rebels.", idiomatic: "On jiyou, Jing's earthen mounds gradually pressed close to the tower; Liu Jin ordered tunnels dug to remove their earth; the outer mound collapsed and crushed nearly all the rebels." },
  { zh: "又於城內作飛橋，懸罩二土山上。", literal: "Within the city they also built flying bridges, suspended to cover the two earthen mounds.", idiomatic: "Within the city they also built flying bridges, suspended to cover the two earthen mounds." },
  { zh: "景眾見飛橋迥出，崩騰而走；", literal: "Jing's troops saw the flying bridges jutting out and fled in panicked collapse;", idiomatic: "Jing's troops saw the flying bridges jutting out and fled in panic;" },
  { zh: "城內擲雉尾炬，焚其東山，樓柵蕩盡，賊積死於城下，乃棄土山不復修，自焚其攻具。", literal: "within the city they threw pheasant-tail torches, burned their eastern mound, towers and palisades were swept away, rebels piled dead below the wall—they then abandoned the earthen mounds and did not rebuild, burning their own siege engines.", idiomatic: "within the city they threw pheasant-tail torches, burned the eastern mound, towers and palisades were swept away, rebels piled dead below the wall—they abandoned the earthen mounds, burned their siege engines, and did not rebuild." },
  { zh: "材官將軍宋嶷降於景，教之引玄武湖水以灌台城，闕前皆為洪流。", literal: "Artificer General Song Ni surrendered to Jing and taught him to draw Xuanwu Lake water to flood the palace city; before the gate all became a torrent.", idiomatic: "Artificer general Song Ni surrendered to Jing and taught him to draw Xuanwu Lake water to flood the palace city; before the gate all became a torrent." },
  { zh: "上征衡州刺史韋粲為散騎常侍，以都督長沙歐陽頠監州事。", literal: "The emperor summoned Hengzhou Inspector Wei Can as Supernumerary Cavalier Attendant and had Changsha Supervisor Ouyang Gu oversee provincial affairs.", idiomatic: "The emperor summoned Hengzhou inspector Wei Can as supernumerary cavalier attendant and had Changsha supervisor Ouyang Gu oversee provincial affairs." },
  { zh: "粲，放之子也。", literal: "Can was Fang's son.", idiomatic: "Can was the son of Wei Fang." },
  { zh: "還，至廬陵，聞侯景亂，粲簡閱部下，得精兵五千，倍道赴援。", literal: "Returning, he reached Luling; hearing of Hou Jing's rebellion, Can inspected his subordinates, got five thousand elite troops, and raced by double stages to aid.", idiomatic: "Returning, he reached Luling; hearing of Hou Jing's rebellion, Can inspected his subordinates, mustered five thousand elite troops, and raced to aid the capital." },
  { zh: "至豫章，聞景已出橫江，粲就內史劉孝儀謀之，孝儀曰：「必如此，當有敕。", literal: "Reaching Yuzhang, he heard Jing had already crossed Hengjiang; Can consulted with Administrator Liu Xiaoyi, who said, \"If it were truly so, there would be an edict.", idiomatic: "Reaching Yuzhang, he heard Jing had already crossed Hengjiang; Can consulted with administrator Liu Xiaoyi, who said, \"If it were truly so, there would be an edict." },
  { zh: "豈可輕信人言，妄相驚動！", literal: "How can one lightly trust men's words and recklessly stir alarm!", idiomatic: "How can one lightly trust rumor and recklessly stir alarm!" },
  { zh: "或恐不然。", literal: "Perhaps it is not so.", idiomatic: "Perhaps it is not so." },
  { zh: "」時孝儀置酒，粲怒，以杯抵地曰：「賊已渡江，便逼宮闕，水陸俱斷，何暇有報！", literal: "\" At the time Xiaoyi was setting out wine; Can angrily dashed his cup to the ground and said, \"The rebels have crossed the river and now press the palace—land and water routes are both cut; how is there time for reports!", idiomatic: "\" At the time Xiaoyi was setting out wine; Can angrily dashed his cup to the ground: \"The rebels have crossed the river and now press the palace—land and water routes are both cut; how is there time for reports!" },
  { zh: "假令無敕，豈得自安！", literal: "Even if there were no edict, how could one rest at ease!", idiomatic: "Even if there were no edict, how could one rest at ease!" },
  { zh: "韋粲今日何情飲酒！", literal: "What mood has Wei Can today to drink wine!", idiomatic: "What mood has Wei Can today to drink wine!" },
  { zh: "」即馳馬出部分。", literal: "\" He immediately galloped out to deploy his forces.", idiomatic: "\" He immediately galloped out to deploy his forces." },
  { zh: "將發，會江州刺史當陽公大心遣使邀粲，粲乃馳往見大心曰：「上游籓鎮，江州去京最近，殿下情計誠宜在前。", literal: "About to set out, he met an envoy from Jiangzhou Inspector Prince of Dangyang Daxin inviting Can; Can galloped to see Daxin and said, \"Among upstream frontier posts, Jiangzhou is nearest the capital—Your Highness by feeling and plan should truly take the lead.", idiomatic: "About to set out, he met an envoy from Jiangzhou inspector Prince Daxin of Dangyang inviting him; Can galloped to see Daxin and said, \"Among upstream frontier posts, Jiangzhou is nearest the capital—Your Highness should truly take the lead." },
  { zh: "但中流任重，當須應接，不可闕鎮。", literal: "But the midstream burden is heavy—you must receive and respond; the post cannot be left vacant.", idiomatic: "But the midstream burden is heavy—you must hold the line; the post cannot be left vacant." },
  { zh: "今宜且張聲勢，移鎮湓城，遣偏將賜隨，於事便足。", literal: "Now you should first raise a show of force, move your seat to Pencheng, and send a subordinate general to follow— that will suffice for the affair.", idiomatic: "Now you should raise a show of force, move your seat to Pencheng, and send a subordinate general to follow—that will suffice." },
  { zh: "」大心然之，遣中兵柳昕帥兵二千人隨粲，粲至南洲，外弟司州刺史柳仲禮亦帥步騎萬餘人至橫江，粲即送糧仗贍給之，並散私金帛以賞其戰士。", literal: "\" Daxin agreed, sent Central Troops Commander Liu Xin leading two thousand men to follow Can; Can reached Nanzhou; his cousin by marriage, Sizhou Inspector Liu Zhongli, also led more than ten thousand foot and horse to Hengjiang; Can immediately sent grain and arms to supply him and distributed private gold and silk to reward his warriors.", idiomatic: "\" Daxin agreed and sent central troops commander Liu Xin with two thousand men to follow Can. Can reached Nanzhou; his cousin by marriage, Sizhou inspector Liu Zhongli, also led more than ten thousand infantry and cavalry to Hengjiang. Can immediately sent grain and arms to supply him and distributed private gold and silk to reward his warriors." },
  { zh: "西豫州刺史裴之高自張公洲遣船度仲禮，丙辰夜，粲、仲禮及宣猛將軍李孝欽、前司州刺史羊鴉仁、南陵太守陳文徹，合軍屯新林王游苑。", literal: "Western Yuzhou Inspector Pei Zhigao sent boats from Zhanggong Isle to ferry Zhongli; on the night of bingchen, Can, Zhongli, Xuanmeng General Li Xiaoqin, former Sizhou Inspector Yang Yaren, and Nanling prefect Chen Wenche combined armies and encamped at the Princes' Pleasure Garden of Xinlin.", idiomatic: "Western Yuzhou inspector Pei Zhigao sent boats from Zhanggong Isle to ferry Zhongli. On the night of bingchen, Can, Zhongli, Xuanmeng general Li Xiaoqin, former Sizhou inspector Yang Yaren, and Nanling prefect Chen Wenche combined armies and encamped at the Princes' Pleasure Garden of Xinlin." },
  { zh: "粲議推仲禮為大都督，報下流眾軍；", literal: "Can proposed making Zhongli supreme commander and reporting this to downstream armies;", idiomatic: "Can proposed making Zhongli supreme commander and reporting this to downstream armies;" },
  { zh: "裴之高自以年位，恥居其下，議累日不決。", literal: "Pei Zhigao, considering his age and rank, was ashamed to serve under him; deliberation went unresolved for days.", idiomatic: "Pei Zhigao, considering his age and rank, was ashamed to serve under him; deliberation went unresolved for days." },
  { zh: "粲抗言於眾曰：「今者同赴國難，義在除賊。", literal: "Can spoke forcefully before the assembly: \"Today we alike go to the state's peril—the righteous task is to destroy the rebels.", idiomatic: "Can spoke forcefully before the assembly: \"Today we alike go to the state's peril—the righteous task is to destroy the rebels." },
  { zh: "所以推柳司州者，正以久捍邊疆，先為侯景所憚；", literal: "The reason for proposing Sizhou Inspector Liu is precisely that he long defended the frontier and is already feared by Hou Jing;", idiomatic: "The reason for proposing Sizhou inspector Liu is precisely that he long defended the frontier and is already feared by Hou Jing;" },
  { zh: "且士馬精銳，無出其前。", literal: "moreover his men and horses are keen—none surpass him.", idiomatic: "moreover his men and horses are keen—none surpass him." },
  { zh: "若論位次，柳在粲下，語其年齒，亦少於粲，直以社稷之計，不得復論。", literal: "If one speaks of rank, Liu is below Can; speaking of age, he is also younger than Can—only for the state's sake can we speak no further of this.", idiomatic: "By rank Liu is below Can; by age he is younger—only for the state's sake can we speak no further of this." },
  { zh: "今日形勢，貴在將和，若人心不同，大事去矣。", literal: "Today's situation values generals in harmony; if hearts differ, the great affair is lost.", idiomatic: "Today's situation values unity among commanders; if hearts differ, the great cause is lost." },
  { zh: "裴公朝之舊德，豈應復挾私情以沮大計！", literal: "Lord Pei is an old pillar of the court—how should he again let private feeling obstruct the great plan!", idiomatic: "Lord Pei is an old pillar of the court—how can he let private feeling obstruct the great plan!" },
  { zh: "粲請為諸軍解之。", literal: "Can asks to settle this for the armies.", idiomatic: "Let Can settle this for the armies." },
  { zh: "」乃單舸至之高營，切讓之曰：「今二宮危逼，猾寇滔天，臣子當戮力同心，豈可自相矛盾！", literal: "\" He then went alone in a single boat to Zhigao's camp and sharply reproached him: \"Now the two palaces are in dire peril, the cunning rebels fill the sky—ministers and sons should join strength in one heart; how can we oppose each other!", idiomatic: "\" He then went alone in a single boat to Zhigao's camp and sharply reproached him: \"Now the two palaces are in dire peril, cunning rebels fill the sky—ministers and sons should join in one heart; how can we oppose each other!" },
  { zh: "豫州必欲立異，鋒鏑便有所歸。", literal: "If Yuzhou insists on standing apart, blades and arrows will know where to go.", idiomatic: "If Yuzhou insists on standing apart, blades and arrows will know where to go." },
  { zh: "」之高垂泣致謝。", literal: "\" Zhigao wept and apologized.", idiomatic: "\" Zhigao wept and apologized." },
  { zh: "遂推仲禮為大都督。", literal: "They then made Zhongli supreme commander.", idiomatic: "They then made Zhongli supreme commander." },
  { zh: "宣城內史楊白華遣其子雄將郡兵繼至，援軍大集，眾十餘萬，緣淮樹柵，景亦於北岸樹柵以應之。", literal: "Xuancheng Administrator Yang Baihua sent his son Xiong leading district troops to follow; relief armies greatly gathered—more than a hundred thousand—building palisades along the Huai; Jing also built palisades on the north bank to match.", idiomatic: "Xuancheng administrator Yang Baihua sent his son Xiong with district troops; relief armies gathered in force—more than a hundred thousand—building palisades along the Huai; Jing also built palisades on the north bank to match." },
  { zh: "裴之高與弟之橫以舟師一萬屯張公洲。", literal: "Pei Zhigao and his brother Zhihéng encamped at Zhanggong Isle with ten thousand river troops.", idiomatic: "Pei Zhigao and his brother Zhihéng encamped at Zhanggong Isle with ten thousand river troops." },
  { zh: "景囚之高弟、侄、子、孫、臨水陳兵，連鎖列於陳前，以鼎鑊、刀鋸隨其後，謂曰：「裴公不降，今即烹之。", literal: "Jing imprisoned Zhigao's younger brothers, nephews, sons, and grandsons; facing the water he arrayed troops, chains lined before the battle line, cauldrons and knives and saws behind, and said, \"If Lord Pei does not surrender, they will be boiled now.", idiomatic: "Jing imprisoned Zhigao's younger brothers, nephews, sons, and grandsons; facing the water he arrayed troops, chains lined before the battle line, cauldrons and knives and saws behind, and said, \"If Lord Pei does not surrender, they will be boiled now." },
  { zh: "」之高召善射者使射其子，再發，皆不中。", literal: "\" Zhigao summoned skilled archers to shoot at his son; twice they loosed, both missed.", idiomatic: "\" Zhigao summoned skilled archers to shoot at his son; twice they loosed, both missed." },
  { zh: "景帥步騎萬人於後渚挑戰，仲禮欲出擊之。", literal: "Jing led ten thousand foot and horse to challenge at Rear Islet; Zhongli wished to sally and strike.", idiomatic: "Jing led ten thousand infantry and cavalry to challenge at Rear Islet; Zhongli wished to sally and strike." },
  { zh: "韋粲曰：「日晚我勞，未可戰也。", literal: "Wei Can said, \"It is late and we are weary—not yet time to fight.", idiomatic: "Wei Can said, \"It is late and we are weary—not yet time to fight." },
  { zh: "」仲禮乃堅壁不出，景亦引退。", literal: "\" Zhongli then held the walls and did not come out; Jing also withdrew.", idiomatic: "\" Zhongli then held the walls and did not come out; Jing also withdrew." },
  { zh: "湘東王繹將銳卒三萬發江陵，留其子綏寧侯方諸居守，咨議參軍劉之迡等三上箋請留，答教不許。", literal: "Prince of Xiangdong Yi was about to lead thirty thousand crack troops from Jiangling, leaving his son Marquis of Suining Fangzhu to hold the seat; Advisory Staff Officer Liu Zhituo and others thrice submitted memorials asking him to stay—the written reply did not permit it.", idiomatic: "Prince Xiao Yi of Xiangdong was about to lead thirty thousand crack troops from Jiangling, leaving his son Marquis Fangzhu of Suining to hold the seat; advisory staff officer Liu Zhituo and others thrice submitted memorials asking him to stay—the written reply refused." },
  { zh: "鄱陽王范遣其將梅伯龍攻王顯貴於壽陽，克其羅城；", literal: "Prince of Poyang Fan sent his general Mei Bolong to attack Wang Xiangui at Shouchun and took the outer wall;", idiomatic: "Prince Xiao Fan of Poyang sent his general Mei Bolong to attack Wang Xiangui at Shouchun and took the outer wall;" },
  { zh: "攻中城，不克而退，范益其眾，使復攻之。", literal: "attacking the inner city, he could not take it and withdrew; Fan increased his forces and had him attack again.", idiomatic: "attacking the inner city, he could not take it and withdrew; Fan increased his forces and had him attack again." },
  { zh: "東魏大將軍澄患民錢濫惡，議不禁民私鑄，但懸稱市門，錢不重五銖，毋得入市。", literal: "Eastern Wei Grand General Cheng was troubled that people's coin was debased and poor; he proposed not forbidding private minting but posting scales at market gates—coin not weighing five zhu was not to enter the market.", idiomatic: "Eastern Wei grand general Gao Cheng was troubled that people's coin was debased; he proposed not forbidding private minting but posting scales at market gates—coin not weighing five zhu was not to enter the market." },
  { zh: "朝議以為年谷不登，請俟它年，乃止。", literal: "Court deliberation held that the year's grain had not ripened and asked to wait for another year—it was then stopped.", idiomatic: "Court deliberation held that the year's harvest had failed and asked to wait for another year—the proposal was dropped." },
  { zh: "魏太師泰殺安定國臣王茂而非其罪。", literal: "Wei Grand Preceptor Tai killed Wang Mao, minister of Anding, though he was not guilty.", idiomatic: "Western Wei grand preceptor Yuwen Tai killed Wang Mao, minister of Anding, though he was not guilty." },
  { zh: "尚書左丞柳慶諫，泰怒曰：「卿黨罪人，亦當坐！", literal: "Left Assistant Director of the Secretariat Liu Qing remonstrated; Tai angrily said, \"You shield the guilty—you too should be punished!", idiomatic: "Left assistant director of the secretariat Liu Qing remonstrated; Yuwen Tai angrily said, \"You shield the guilty—you too should be punished!" },
  { zh: "」執慶於前。", literal: "\" He seized Qing before him.", idiomatic: "\" He seized Qing before him." },
  { zh: "慶辭色不撓，曰：「慶聞君蔽於事為不明，臣知而不爭為不忠。", literal: "Qing's words and bearing did not bend; he said, \"Qing has heard that a lord blinded to affairs is unwise, and a minister who knows yet does not contend is disloyal.", idiomatic: "Qing's words and bearing did not bend; he said, \"I have heard that a lord blinded to affairs is unwise, and a minister who knows yet does not contend is disloyal." },
  { zh: "慶既竭忠，不敢愛死，但懼公為不明耳。", literal: "Qing having exhausted loyalty, dares not cherish life—only fears that my lord is unwise.", idiomatic: "Having exhausted my loyalty, I dare not cherish life—only fear that my lord is unwise." },
  { zh: "」泰寤，亟使赦茂，不及，乃賜茂家錢帛，曰：「以旌吾過。", literal: "\" Tai awoke and urgently sent to pardon Mao—too late; he then bestowed money and silk on Mao's family, saying, \"To mark my fault.", idiomatic: "\" Yuwen Tai awoke and urgently sent to pardon Mao—too late; he then bestowed money and silk on Mao's family, saying, \"To mark my fault." },
  { zh: "丙辰晦，柳仲禮夜入韋粲營，部分眾軍。", literal: "On the last day of bingchen, Liu Zhongli entered Wei Can's camp by night and deployed the armies.", idiomatic: "On the last day of bingchen, Liu Zhongli entered Wei Can's camp by night and deployed the armies." },
  { zh: "旦日，會戰，諸將各有據守，令粲頓青塘。", literal: "At dawn, they joined battle; each general had his post; Can was ordered to hold Qingtang.", idiomatic: "At dawn they joined battle; each general had his post; Can was ordered to hold Qingtang." },
  { zh: "粲以青塘當石頭中路，賊必爭之，頗憚之。", literal: "Can, because Qingtang lay on the central road to Shitou and the rebels would surely contest it, was quite afraid.", idiomatic: "Can, because Qingtang lay on the central road to Shitou and the rebels would surely contest it, was quite afraid." },
  { zh: "仲禮曰：「青塘要地，非兄不可；", literal: "Zhongli said, \"Qingtang is a vital ground—no one but elder brother will do;", idiomatic: "Zhongli said, \"Qingtang is vital ground—no one but you will do;" },
  { zh: "若疑兵少，當更遣軍相助。", literal: "if you fear too few troops, more should be sent to assist.", idiomatic: "if you fear too few troops, more will be sent to assist." },
  { zh: "」乃使直閣將軍劉叔胤助之。", literal: "\" He then sent Direct Attendant General Liu Shuyin to assist.", idiomatic: "\" He then sent direct attendant general Liu Shuyin to assist." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
